-- Name: discuss_channel; Type: TABLE; Schema: public; Owner: odoo
--

CREATE TABLE public.discuss_channel (
    id integer NOT NULL,
    discuss_category_id integer,
    parent_channel_id integer,
    from_message_id integer,
    group_public_id integer,
    create_uid integer,
    write_uid integer,
    name character varying NOT NULL,
    channel_type character varying NOT NULL,
    default_display_mode character varying,
    member_indices character varying,
    sfu_channel_uuid character varying,
    sfu_server_url character varying,
    uuid character varying(50),
    description text,
    active boolean,
    is_readonly boolean,
    last_interest_dt timestamp without time zone,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    CONSTRAINT discuss_channel_group_public_id_check CHECK ((((channel_type)::text = 'channel'::text) OR (group_public_id IS NULL))),
    CONSTRAINT discuss_channel_member_indices_channel_check CHECK ((((channel_type)::text = 'chat'::text) OR (member_indices IS NULL))),
    CONSTRAINT discuss_channel_member_indices_chat_check CHECK ((((channel_type)::text <> 'chat'::text) OR ((member_indices IS NOT NULL) AND (TRIM(BOTH FROM member_indices) <> ''::text)))),
    CONSTRAINT discuss_channel_readonly_channel_type_check CHECK (((is_readonly IS NOT TRUE) OR ((channel_type)::text = 'channel'::text)))
);


ALTER TABLE public.discuss_channel OWNER TO odoo;

