--
-- Name: res_device; Type: VIEW; Schema: public; Owner: odoo
--

CREATE VIEW public.res_device AS
 SELECT id,
    session_identifier,
    user_id,
    ip_address,
    user_agent,
    country,
    city,
    first_activity,
    last_activity,
    revoked
   FROM public.res_device_log l1
  WHERE ((revoked IS NOT TRUE) AND (NOT (EXISTS ( SELECT 1
           FROM public.res_device_log l2
          WHERE ((l2.user_id = l1.user_id) AND ((l2.session_identifier)::text = (l1.session_identifier)::text) AND ((l2.ip_address)::text = (l1.ip_address)::text) AND ((l2.user_agent)::text = (l1.user_agent)::text) AND (l2.id > l1.id) AND (l2.revoked IS NOT TRUE))))));


