--
-- Name: res_session; Type: VIEW; Schema: public; Owner: odoo
--

CREATE VIEW public.res_session AS
 SELECT id,
    session_identifier,
    user_id,
    last_activity,
    revoked
   FROM public.res_device d1
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.res_device d2
          WHERE ((d2.user_id = d1.user_id) AND ((d2.session_identifier)::text = (d1.session_identifier)::text) AND (d2.id > d1.id)))));


ALTER VIEW public.res_session OWNER TO odoo;

