    CONSTRAINT resource_calendar_attendance_check_duration_hours CHECK (((duration_hours > (0)::double precision) AND (duration_hours <= (24)::double precision))),
    CONSTRAINT resource_calendar_attendance_check_interval CHECK (((recurrency IS NOT TRUE) OR (recurrency_interval >= 1))),
