--
-- Name: sale_order_line; Type: TABLE; Schema: public; Owner: odoo
--

CREATE TABLE public.sale_order_line (
    id integer NOT NULL,
    product_id integer,
    order_id integer NOT NULL,
    sequence integer,
    company_id integer,
    currency_id integer,
    order_partner_id integer,
    salesman_id integer,
    product_uom_id integer,
    linked_line_id integer,
    combo_item_id integer,
    customer_lead integer NOT NULL,
    section_uom_id integer,
    create_uid integer,
    write_uid integer,
    state character varying,
    display_type character varying,
    virtual_id character varying,
    linked_virtual_id character varying,
    qty_delivered_method character varying,
    invoice_status character varying,
    analytic_distribution jsonb,
    extra_tax_data jsonb,
    name text,
    product_uom_qty numeric NOT NULL,
    price_unit numeric NOT NULL,
    discount numeric,
    price_subtotal numeric,
    price_total numeric,
    price_reduce_taxexcl numeric,
    price_reduce_taxinc numeric,
    qty_delivered numeric,
    qty_invoiced numeric,
    qty_to_invoice numeric,
    untaxed_amount_invoiced numeric,
    untaxed_amount_to_invoice numeric,
    section_qty numeric,
    is_downpayment boolean,
    is_expense boolean,
    collapse_prices boolean,
    collapse_composition boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    technical_price_unit double precision,
    price_tax double precision,
    is_delivery boolean,
    edi_customer_product_ref character varying,
    reward_id integer,
    coupon_id integer,
    reward_identifier_code character varying,
    points_cost double precision,
    warehouse_id integer,
    alerts jsonb,
    dsayur_note character varying(200),
    CONSTRAINT sale_order_line_accountable_required_fields CHECK (((display_type IS NOT NULL) OR is_downpayment OR (product_uom_id IS NOT NULL))),
    CONSTRAINT sale_order_line_non_accountable_null_fields CHECK (((display_type IS NULL) OR ((product_id IS NULL) AND (price_unit = (0)::numeric) AND (product_uom_qty = (0)::numeric) AND (product_uom_id IS NULL) AND (customer_lead = 0)))),
    CONSTRAINT sale_order_line_section_fields_null CHECK ((((display_type)::text = ANY ((ARRAY['line_section'::character varying, 'line_subsection'::character varying])::text[])) OR ((section_qty = (0)::numeric) AND (section_uom_id IS NULL))))
);


ALTER TABLE public.sale_order_line OWNER TO odoo;

