-- Name: CONSTRAINT sale_order_line_non_accountable_null_fields ON sale_order_line; Type: COMMENT; Schema: public; Owner: odoo
--

COMMENT ON CONSTRAINT sale_order_line_non_accountable_null_fields ON public.sale_order_line IS 'CHECK(display_type IS NULL OR (product_id IS NULL AND price_unit = 0 AND product_uom_qty = 0 AND product_uom_id IS NULL AND customer_lead = 0))';


--
-- Name: CONSTRAINT sale_order_line_section_fields_null ON sale_order_line; Type: COMMENT; Schema: public; Owner: odoo
--

COMMENT ON CONSTRAINT sale_order_line_section_fields_null ON public.sale_order_line IS 'CHECK(display_type IN (''line_section'', ''line_subsection'') OR (section_qty = 0 AND section_uom_id IS NULL))';


