2154	16	\N	1	1	Comparator Page	\N	website_sale.product_compare	qweb	website_sale/templates/comparison_templates.xml	primary	\N	{"en_US": "<t name=\\"Comparator Page\\" t-name=\\"website_sale.product_compare\\">\\n        <t t-call=\\"website.layout\\" additional_title.translate=\\"Shop Comparator\\">\\n            <div id=\\"wrap\\" class=\\"o_wsale_comparison_page\\">\\n                <div class=\\"oe_structure oe_empty\\" id=\\"oe_structure_website_sale_comparison_product_compare_1\\"/>\\n                <div t-attf-class=\\"oe_website_sale pb-5 #{website.shop_page_container == 'fluid' and 'container-fluid' or 'container'}\\">\\n                    <h1 class=\\"h4 mt-4 mb-3\\">Compare Products</h1>\\n\\n                    <!-- Mini sticky product overview (initially hidden) -->\\n                    <div class=\\"o_wsale_comparison_mini_sticky fixed-top d-none bg-body\\" id=\\"miniStickyComparison\\">\\n                        <div t-attf-class=\\"px-3 #{website.shop_page_container == 'fluid' and 'container-fluid' or 'container'}\\">\\n                            <div class=\\"o_wsale_comparison_scroll_container overflow-x-auto\\">\\n                                <ul class=\\"list-unstyled d-flex align-items-stretch mb-0 py-3\\">\\n                                    <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column flex-shrink-0\\">\\n                                        <a t-att-href=\\"product.website_url\\" class=\\"d-flex align-items-center gap-2 text-decoration-none text-truncate\\">\\n                                            <t t-set=\\"combination_info\\" t-value=\\"product._get_combination_info_variant()\\"/>\\n                                            <div class=\\"o_mini_product_img_container flex-shrink-0\\">\\n                                                <img t-att-src=\\"product._get_image_1024_url()\\" class=\\"img-fluid flex-shrink-0 w-100 h-100 rounded border object-fit-cover\\" t-att-alt=\\"combination_info['display_name']\\"/>\\n                                            </div>\\n                                            <div class=\\"text-truncate\\">\\n                                                <h6 class=\\"flex-grow-1 text-truncate mb-0 small\\" t-out=\\"combination_info['display_name']\\"/>\\n                                                <div t-if=\\"not combination_info['hide_price']\\" class=\\"text-wrap\\">\\n                                                    <small class=\\"mb-0 h6 text-body\\" t-out=\\"combination_info['price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                                    <del t-if=\\"combination_info.get('compare_list_price') and (combination_info['compare_list_price'] &gt; combination_info['price'])\\" class=\\"ms-1 mb-0 text-muted h6 small\\" t-out=\\"combination_info['compare_list_price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                                    <del t-else=\\"\\" t-attf-class=\\"ms-1 mb-0 text-muted h6 small {{'' if combination_info['has_discounted_price'] else 'd-none'}}\\" t-out=\\"combination_info['list_price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                                </div>\\n                                            </div>\\n                                        </a>\\n                                    </li>\\n                                </ul>\\n                            </div>\\n                        </div>\\n                    </div>\\n\\n                    <div class=\\"overflow-x-auto\\">\\n                        <div class=\\"table-comparator position-relative\\" id=\\"o_comparelist_table\\">\\n                            <ul class=\\"list-unstyled d-flex mb-0\\">\\n                                <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0\\">\\n                                    <t t-set=\\"combination_info\\" t-value=\\"product._get_combination_info_variant()\\"/>\\n                                    <a t-att-href=\\"product.website_url\\">\\n                                        <img t-att-src=\\"product._get_image_1024_url()\\" class=\\"img img-fluid w-100 h-100 object-fit-cover border rounded\\" alt=\\"Product image\\"/>\\n                                    </a>\\n                                    <button class=\\"o_comparelist_remove btn position-absolute top-0 end-0 mx-3 my-2 p-2 rounded-circle bg-white-75 lh-1\\" aria-label=\\"Remove product from comparison\\" t-att-data-product-id=\\"product.id\\">\\n                                        <i class=\\"oi\\" data-icon=\\"close_small\\"/>\\n                                    </button>\\n                                </li>\\n                            </ul>\\n                            <ul class=\\"list-unstyled d-flex mb-0 pt-3 pb-5\\">\\n                                <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0\\">\\n                                    <t t-set=\\"combination_info\\" t-value=\\"product._get_combination_info_variant()\\"/>\\n                                    <div id=\\"o_comparelist_product_name\\" class=\\"product_summary d-flex flex-column h-100\\">\\n                                        <a t-att-href=\\"product.website_url\\">\\n                                            <h6 t-out=\\"product.display_name\\"/>\\n                                        </a>\\n                                        <span t-if=\\"product._is_sold_out()\\" class=\\"o_wsale_stock_badge badge text-bg-danger align-self-start align-top\\">\\n                                            <i class=\\"oi oi-filled me-2 text-danger\\" data-icon=\\"circle\\" aria-hidden=\\"true\\"/>\\n                                            Out of stock\\n                                        </span>\\n                                        <span t-if=\\"not combination_info['hide_price']\\">\\n                                            <span t-out=\\"combination_info['price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                            <del t-if=\\"combination_info.get('compare_list_price') and (combination_info['compare_list_price'] &gt; combination_info['price'])\\" class=\\"me-2 text-muted text-nowrap\\" t-out=\\"combination_info['compare_list_price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                            <del t-else=\\"\\" t-attf-class=\\"text-muted me-2 text-nowrap {{'' if combination_info['has_discounted_price'] else 'd-none'}}\\" t-out=\\"combination_info['list_price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                            <small t-if=\\"'base_unit_price' in combination_info\\" class=\\"d-block text-muted\\">\\n                                                <t t-call=\\"website_sale.base_unit_price\\" base_unit_price=\\"combination_info['base_unit_price']\\"/>\\n                                            </small>\\n                                        </span>\\n                                        <div class=\\"mt-auto pt-3\\">\\n                                            <a t-if=\\"combination_info['prevent_sale']\\" t-att-href=\\"website._get_contact_us_url(combination_info['display_name'])\\" class=\\"btn btn-primary btn_cta\\">\\n                                               Contact Us\\n                                            </a>\\n                                            <button t-else=\\"\\" name=\\"add_to_cart\\" class=\\"btn btn-primary\\" t-att-data-product-id=\\"product.id\\" t-att-data-product-template-id=\\"product.product_tmpl_id.id\\" t-att-data-product-type=\\"product.product_tmpl_id.type\\" t-att-data-ptav-ids=\\"json.dumps(product.product_template_attribute_value_ids.ids)\\" t-att-data-show-quantity=\\"is_view_active('website_sale.product_quantity')\\" t-att-disabled=\\"product._is_sold_out()\\">\\n                                                <i class=\\"oi me-2\\" data-icon=\\"shopping_cart\\" aria-hidden=\\"true\\"/>Add to Cart\\n                                            </button>\\n                                        </div>\\n                                    </div>\\n                                </li>\\n                            </ul>\\n                            <div t-foreach=\\"attrib_categories\\" t-as=\\"category\\">\\n                                <div class=\\"w-100 py-3 bg-light bg-opacity-50\\">\\n                                    <h6 class=\\"d-table position-sticky start-0 mb-0 ps-2\\">\\n                                        <span t-if=\\"category\\" t-field=\\"category.name\\"/>\\n                                        <t t-else=\\"\\">Uncategorized</t>\\n                                    </h6>\\n                                </div>\\n                                <ul t-foreach=\\"attrib_categories[category]\\" t-as=\\"attribute\\" t-att-class=\\"'list-unstyled d-flex mb-0 py-3 o_ws_category_%d %s' % (category.id, 'border-bottom' if not attribute_last else '')\\">\\n                                    <li t-foreach=\\"attrib_categories[category][attribute]\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column d-flex flex-column flex-shrink-0\\">\\n                                        <div id=\\"o_comparelist_attribute\\">\\n                                            <t t-if=\\"attrib_categories[category][attribute][product]\\">\\n                                                <div class=\\"small text-muted\\" t-field=\\"attribute.name\\"/>\\n                                                <t t-foreach=\\"attrib_categories[category][attribute][product]\\" t-as=\\"ptav\\">\\n                                                    <small t-field=\\"ptav.name\\"/><t t-if=\\"not ptav_last\\">, </t>\\n                                                </t>\\n                                            </t>\\n                                            <t t-else=\\"\\">\\n                                                <div class=\\"small text-muted\\" t-field=\\"attribute.name\\"/>\\n                                                <h6 class=\\"small text-muted mb-0\\">-</h6>\\n                                            </t>\\n                                        </div>\\n                                    </li>\\n                                </ul>\\n                            </div>\\n                            <t t-if=\\"is_view_active('website_sale.product_tags') and any([product.all_product_tag_ids.filtered('visible_to_customers') for product in products])\\">\\n                                <h6 class=\\"d-table position-sticky start-0 mb-0\\">Tags</h6>\\n                                <ul class=\\"list-unstyled d-flex border-bottom mb-0 py-3\\">\\n                                    <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column d-flex flex-column align-items-center flex-shrink-0\\">\\n                                        <div class=\\"small text-muted\\">Tags</div>\\n                                        <t t-call=\\"website_sale.product_tags\\" all_product_tags=\\"product.all_product_tag_ids\\"/>\\n                                    </li>\\n                                </ul>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </div>\\n                <div class=\\"oe_structure\\" id=\\"oe_structure_website_sale_comparison_product_compare_2\\"/>\\n                <div class=\\"align-items-end bottom-0 d-flex end-0 justify-content-end o_not_editable p-0 position-absolute top-0 start-0 pe-none\\">\\n                    <div class=\\"o_wsale_comparison_bottom_bar sticky-bottom flex-shrink-0 w-100 bg-body pe-auto\\">\\n                        <div t-attf-class=\\"d-flex align-items-center py-3 #{website.shop_page_container == 'fluid' and 'container-fluid' or 'container'}\\">\\n                            <a href=\\"/shop\\" class=\\"btn btn-link ps-0 text-decoration-none\\" aria-label=\\"Continue shopping\\">\\n                                <i class=\\"oi me-1\\" data-icon=\\"chevron_backward\\"/> Back to shop\\n                            </a>\\n                            <button class=\\"button btn btn-light ms-auto\\" aria-label=\\"Remove all products from comparison\\" name=\\"comparison_clear_all_button\\">\\n                                Remove all\\n                            </button>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Comparator Page" t-name="website_sale.product_compare">\n        <t t-call="website.layout" additional_title.translate="Shop Comparator">\n            <div id="wrap" class="o_wsale_comparison_page">\n                <div class="oe_structure oe_empty" id="oe_structure_website_sale_comparison_product_compare_1"/>\n                <div t-attf-class="oe_website_sale pb-5 #{website.shop_page_container == 'fluid' and 'container-fluid' or 'container'}">\n                    <h1 class="h4 mt-4 mb-3">Compare Products</h1>\n\n                    <!-- Mini sticky product overview (initially hidden) -->\n                    <div class="o_wsale_comparison_mini_sticky fixed-top d-none bg-body" id="miniStickyComparison">\n                        <div t-attf-class="px-3 #{website.shop_page_container == 'fluid' and 'container-fluid' or 'container'}">\n                            <div class="o_wsale_comparison_scroll_container overflow-x-auto">\n                                <ul class="list-unstyled d-flex align-items-stretch mb-0 py-3">\n                                    <li t-foreach="products" t-as="product" class="o_wsale_compare_table_column flex-shrink-0">\n                                        <a t-att-href="product.website_url" class="d-flex align-items-center gap-2 text-decoration-none text-truncate">\n                                            <t t-set="combination_info" t-value="product._get_combination_info_variant()"/>\n                                            <div class="o_mini_product_img_container flex-shrink-0">\n                                                <img t-att-src="product._get_image_1024_url()" class="img-fluid flex-shrink-0 w-100 h-100 rounded border object-fit-cover" t-att-alt="combination_info['display_name']"/>\n                                            </div>\n                                            <div class="text-truncate">\n                                                <h6 class="flex-grow-1 text-truncate mb-0 small" t-out="combination_info['display_name']"/>\n                                                <div t-if="not combination_info['hide_price']" class="text-wrap">\n                                                    <small class="mb-0 h6 text-body" t-out="combination_info['price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                                    <del t-if="combination_info.get('compare_list_price') and (combination_info['compare_list_price'] &gt; combination_info['price'])" class="ms-1 mb-0 text-muted h6 small" t-out="combination_info['compare_list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                                    <del t-else="" t-attf-class="ms-1 mb-0 text-muted h6 small {{'' if combination_info['has_discounted_price'] else 'd-none'}}" t-out="combination_info['list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                                </div>\n                                            </div>\n                                        </a>\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class="overflow-x-auto">\n                        <div class="table-comparator position-relative" id="o_comparelist_table">\n                            <ul class="list-unstyled d-flex mb-0">\n                                <li t-foreach="products" t-as="product" class="o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0">\n                                    <t t-set="combination_info" t-value="product._get_combination_info_variant()"/>\n                                    <a t-att-href="product.website_url">\n                                        <img t-att-src="product._get_image_1024_url()" class="img img-fluid w-100 h-100 object-fit-cover border rounded" alt="Product image"/>\n                                    </a>\n                                    <button class="o_comparelist_remove btn position-absolute top-0 end-0 mx-3 my-2 p-2 rounded-circle bg-white-75 lh-1" aria-label="Remove product from comparison" t-att-data-product-id="product.id">\n                                        <i class="oi" data-icon="close_small"/>\n                                    </button>\n                                </li>\n                            </ul>\n                            <ul class="list-unstyled d-flex mb-0 pt-3 pb-5">\n                                <li t-foreach="products" t-as="product" class="o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0">\n                                    <t t-set="combination_info" t-value="product._get_combination_info_variant()"/>\n                                    <div id="o_comparelist_product_name" class="product_summary d-flex flex-column h-100">\n                                        <a t-att-href="product.website_url">\n                                            <h6 t-out="product.display_name"/>\n                                        </a>\n                                        <span t-if="product._is_sold_out()" class="o_wsale_stock_badge badge text-bg-danger align-self-start align-top">\n                                            <i class="oi oi-filled me-2 text-danger" data-icon="circle" aria-hidden="true"/>\n                                            Out of stock\n                                        </span>\n                                        <span t-if="not combination_info['hide_price']">\n                                            <span t-out="combination_info['price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <del t-if="combination_info.get('compare_list_price') and (combination_info['compare_list_price'] &gt; combination_info['price'])" class="me-2 text-muted text-nowrap" t-out="combination_info['compare_list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <del t-else="" t-attf-class="text-muted me-2 text-nowrap {{'' if combination_info['has_discounted_price'] else 'd-none'}}" t-out="combination_info['list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <small t-if="'base_unit_price' in combination_info" class="d-block text-muted">\n                                                <t t-call="website_sale.base_unit_price" base_unit_price="combination_info['base_unit_price']"/>\n                                            </small>\n                                        </span>\n                                        <div class="mt-auto pt-3">\n                                            <a t-if="combination_info['prevent_sale']" t-att-href="website._get_contact_us_url(combination_info['display_name'])" class="btn btn-primary btn_cta">\n                                               Contact Us\n                                            </a>\n                                            <button t-else="" name="add_to_cart" class="btn btn-primary" t-att-data-product-id="product.id" t-att-data-product-template-id="product.product_tmpl_id.id" t-att-data-product-type="product.product_tmpl_id.type" t-att-data-ptav-ids="json.dumps(product.product_template_attribute_value_ids.ids)" t-att-data-show-quantity="is_view_active('website_sale.product_quantity')" t-att-disabled="product._is_sold_out()">\n                                                <i class="oi me-2" data-icon="shopping_cart" aria-hidden="true"/>Add to Cart\n                                            </button>\n                                        </div>\n                                    </div>\n                                </li>\n                            </ul>\n                            <div t-foreach="attrib_categories" t-as="category">\n                                <div class="w-100 py-3 bg-light bg-opacity-50">\n                                    <h6 class="d-table position-sticky start-0 mb-0 ps-2">\n                                        <span t-if="category" t-field="category.name"/>\n                                        <t t-else="">Uncategorized</t>\n                                    </h6>\n                                </div>\n                                <ul t-foreach="attrib_categories[category]" t-as="attribute" t-att-class="'list-unstyled d-flex mb-0 py-3 o_ws_category_%d %s' % (category.id, 'border-bottom' if not attribute_last else '')">\n                                    <li t-foreach="attrib_categories[category][attribute]" t-as="product" class="o_wsale_compare_table_column d-flex flex-column flex-shrink-0">\n                                        <div id="o_comparelist_attribute">\n                                            <t t-if="attrib_categories[category][attribute][product]">\n                                                <div class="small text-muted" t-field="attribute.name"/>\n                                                <t t-foreach="attrib_categories[category][attribute][product]" t-as="ptav">\n                                                    <small t-field="ptav.name"/><t t-if="not ptav_last">, </t>\n                                                </t>\n                                            </t>\n                                            <t t-else="">\n                                                <div class="small text-muted" t-field="attribute.name"/>\n                                                <h6 class="small text-muted mb-0">-</h6>\n                                            </t>\n                                        </div>\n                                    </li>\n                                </ul>\n                            </div>\n                            <t t-if="is_view_active('website_sale.product_tags') and any([product.all_product_tag_ids.filtered('visible_to_customers') for product in products])">\n                                <h6 class="d-table position-sticky start-0 mb-0">Tags</h6>\n                                <ul class="list-unstyled d-flex border-bottom mb-0 py-3">\n                                    <li t-foreach="products" t-as="product" class="o_wsale_compare_table_column d-flex flex-column align-items-center flex-shrink-0">\n                                        <div class="small text-muted">Tags</div>\n                                        <t t-call="website_sale.product_tags" all_product_tags="product.all_product_tag_ids"/>\n                                    </li>\n                                </ul>\n                            </t>\n                        </div>\n                    <