2213	16	\N	1	1	Products	\N	website_sale.products	qweb	website_sale/templates/shop_page_templates.xml	primary	\N	{"en_US": "<t name=\\"Products\\" t-name=\\"website_sale.products\\">\\n        <t t-set=\\"website_sale_sortable\\" t-value=\\"website._get_product_sort_mapping()\\"/>\\n        <t t-call=\\"website.layout\\" additional_title=\\"category.name\\" website_sale_sortable=\\"website_sale_sortable\\">\\n            <t t-set=\\"grid_block_name\\">Grid</t>\\n            <t t-set=\\"product_block_name\\">Product</t>\\n\\n            <!-- Qweb variable defining the class suffix for navbar items.\\n                 Change accordingly to the derired visual result (eg. `primary`, `dark`...)-->\\n            <t t-set=\\"navClass\\" t-valuef=\\"light\\"/>\\n\\n            <!-- Check for active options: the stored value may be used in sub-templates too  -->\\n            <t t-set=\\"opt_wsale_fullwidth\\" t-value=\\"website.shop_page_container == 'fluid'\\"/>\\n            <t t-set=\\"opt_wsale_categories\\" t-value=\\"is_view_active('website_sale.products_categories')\\"/>\\n            <t t-set=\\"opt_wsale_attributes\\" t-value=\\"is_view_active('website_sale.products_attributes')\\"/>\\n            <t t-set=\\"opt_wsale_filter_price\\" t-value=\\"is_view_active('website_sale.filter_products_price')\\"/>\\n            <t t-set=\\"opt_wsale_filter_tags\\" t-value=\\"is_view_active('website_sale.filter_products_tags')\\"/>\\n            <t t-set=\\"opt_wsale_design_grid\\" t-value=\\"'o_wsale_products_opt_design_grid' in website.shop_opt_products_design_classes\\"/>\\n\\n            <t t-set=\\"opt_wsale_categories_top\\" t-value=\\"is_view_active('website_sale.products_categories_top')\\"/>\\n            <t t-set=\\"opt_wsale_attributes_top\\" t-value=\\"is_view_active('website_sale.products_attributes_top')\\"/>\\n            <t t-set=\\"opt_wsale_floating_bar\\" t-value=\\"is_view_active('website_sale.floating_bar')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_shop_title\\" t-value=\\"is_view_active('website_sale.products_shop_title')\\"/>\\n            <t t-set=\\"opt_wsale_shop_title_align\\" t-value=\\"is_view_active('website_sale.products_shop_title_align')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_category_title\\" t-value=\\"website.show_category_title\\"/>\\n            <t t-set=\\"opt_wsale_show_category_description\\" t-value=\\"website.show_category_description\\"/>\\n            <t t-set=\\"opt_wsale_category_align\\" t-value=\\"website.align_category_content\\"/>\\n\\n            <t t-set=\\"show_price_filter\\" t-value=\\"opt_wsale_filter_price and opt_wsale_attributes\\"/>\\n            <t t-set=\\"hasLeftColumn\\" t-value=\\"                     (opt_wsale_categories and categories)                     or (opt_wsale_attributes and (attributes or all_tags or opt_wsale_filter_price))                     or show_price_filter                     or show_on_sale_filter                     or show_in_stock_filter                 \\"/>\\n\\n            <t t-set=\\"isFilteringByPrice\\" t-if=\\"opt_wsale_filter_price\\" t-value=\\"float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)\\"/>\\n            <t t-set=\\"isSortingBy\\" t-value=\\"[sort for sort in website_sale_sortable if sort[0]==request.params.get('order', '')]\\"/>\\n\\n            <t t-set=\\"wsale_has_filters_btn\\" t-value=\\"opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top\\"/>\\n            <t t-set=\\"wsale_has_filters_btn_lg\\" t-value=\\"opt_wsale_attributes_top\\"/>\\n\\n            <div id=\\"wrap\\" class=\\"o_wsale_products_page\\">\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_1\\"/>\\n                <div id=\\"o_wsale_container\\" t-attf-class=\\"oe_website_sale                         {{opt_wsale_fullwidth and 'container-fluid o_wsale_page_fluid' or 'o_wsale_page_contained container'}}                         {{opt_wsale_categories_top and 'o_wsale_has_filmstrip'}}                         {{opt_wsale_floating_bar and 'o_wsale_has_floating_bar'}}                         {{hasLeftColumn and 'o_wsale_has_sidebar'}}                         {{editionPreviews and 'o_wsale_edit_preview_enabled'}}                         {{opt_wsale_design_grid and 'o_wsale_uses_grid_design'}}\\" t-att-data-ppg=\\"ppg\\" t-att-data-ppr=\\"ppr\\" t-att-data-default-sort=\\"website.shop_default_sort\\">\\n                    <div class=\\"row o_wsale_products_main_row flex-nowrap\\">\\n                        <aside t-if=\\"hasLeftColumn\\" id=\\"products_grid_before\\" class=\\"d-none d-lg-block position-sticky align-self-start col clearfix pt-2\\">\\n                            <t t-call=\\"website_sale.sidebar_dropzone_at_top\\"/>\\n                            <div class=\\"o_wsale_products_grid_before_rail ms-n2 px-lg-2 ps-2 overflow-y-scroll\\">\\n                                <t t-set=\\"is_sidebar_collapsible\\" t-value=\\"is_view_active('website_sale.products_categories_list_collapsible')\\"/>\\n                                <div t-if=\\"opt_wsale_categories\\" t-att-class=\\"'products_categories'                                                 + (' accordion accordion-flush' if is_sidebar_collapsible else ' mb-3')\\">\\n                                    <t t-call=\\"website_sale.products_categories_list\\"/>\\n                                </div>\\n                                <t t-set=\\"has_active_filters\\" t-value=\\"(                                         attrib_values                                         or tags                                         or (show_on_sale_filter and on_sale_active)                                         or (show_in_stock_filter and in_stock_active)                                         or (show_price_filter and isFilteringByPrice)                                     )\\"/>\\n    