ory.id\\" t-attf-class=\\"d-flex flex-column gap-2                                     {{_header_has_content and 'pt-4 pb-3' or opt_wsale_design_grid and 'py-3'}}                                     {{category and 'o_wsale_products_header_is_category' or 'o_wsale_products_header_is_shop'}}                                     {{opt_wsale_show_category_title and 'o_wsale_products_header_show_category_title'}}                                     {{opt_wsale_show_category_description and 'o_wsale_products_header_show_category_description'}}                                     {{opt_wsale_category_align and 'o_wsale_products_header_category_center_content'}}                                     {{opt_wsale_show_shop_title and 'o_wsale_products_header_show_shop_title'}}                                     {{opt_wsale_shop_title_align and 'o_wsale_products_header_shop_center_content'}}\\">\\n                                <t t-if=\\"category and not search\\" t-call=\\"website_sale.products_breadcrumb\\" _classes.f=\\"w-100 p-0 mb-0 small {{not opt_wsale_show_category_title and 'mb-2 mb-lg-0'}}\\"/>\\n                                <h1 t-if=\\"category or search\\" t-attf-class=\\"o_wsale_category_title d-flex gap-1 align-items-center mb-0 lh-lg {{search and bool(category) and 'mb-2'}} {{search and 'o_wsale_category_title_is_search base-fs font-sans-serif' or 'fs-3'}}\\">\\n                                    <t t-if=\\"search and category\\">\\n                                        <span class=\\"text-muted\\">Searching</span>\\n                                        <span class=\\"badge text-bg-info fw-normal base-fs\\">\\n                                            <t t-out=\\"search\\"/>\\n                                            <a title=\\"Clear search for this category\\" t-att-href=\\"keep(search=0, **reset_filters)\\" class=\\"link-info\\">\\n                                                <i class=\\"oi\\" data-icon=\\"close_small\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                        <span class=\\"text-muted\\">in</span>\\n                                        <span class=\\"badge text-bg-primary fw-normal base-fs\\">\\n                                            <t t-out=\\"category.name\\"/>\\n                                            <a title=\\"Search globally\\" t-att-href=\\"keep(shop_path, search=search, **reset_filters)\\">\\n                                                <i class=\\"oi\\" data-icon=\\"close_small\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                    </t>\\n                                    <span t-elif=\\"search\\">\\n                                        <span class=\\"text-muted\\">Search results for </span>'<strong t-out=\\"search\\"/>' <small t-if=\\"search_count\\" class=\\"text-muted\\"> (<t t-out=\\"search_count\\"/>)</small>\\n                                    </span>\\n                                    <t t-elif=\\"category\\">\\n                                        <span t-field=\\"category.name\\"/>\\n                                    </t>\\n                                </h1>\\n                                <div class=\\"o_wsale_shop_title\\" t-if=\\"not category and not search\\">\\n                                    <h1 class=\\"h4-fs\\">\\n                                        All products\\n                                    </h1>\\n                                </div>\\n                                <t t-if=\\"category\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Drag blocks here to customize the header of\\n                                        the \\"<t t-out=\\"category.name\\"/>\\" category\\n                                    </t>\\n                                    <div id=\\"category_header\\" class=\\"o_wsale_category_description\\" t-att-data-editor-message=\\"editor_msg\\" t-field=\\"category.website_description\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Drag blocks here to customize the Shop page header\\n                                    </t>\\n                                    <div id=\\"oe_structure_products_header_shop\\" class=\\"oe_structure oe_empty\\" t-att-data-editor-message=\\"editor_msg\\"/>\\n                                </t>\\n                                <t t-if=\\"opt_wsale_categories_top and category_entries\\" t-call=\\"website_sale.filmstrip_categories\\" entries=\\"category_entries\\"/>\\n                                <div t-if=\\"not opt_wsale_floating_bar\\" class=\\"products_header d-flex gap-1 gap-lg-2 gap-xl-3\\">\\n                                    <div class=\\"o_wsale_products_header_inner d-flex justify-content-between w-100\\">\\n                                        <t t-if=\\"is_view_active('website_sale.search')\\">\\n                                            <!-- Desktop Search button -->\\n                                            <div class=\\"o_wsale_products_header_search_form_container d-none d-sm-inline-block flex-grow-1 me-auto\\">\\n                                                <t t-if=\\"category\\" t-set=\\"placeholder\\" t-valuef.translate=\\"Search in {{category.name}}\\"/>\\n                                                <t t-call=\\"website_sale.search\\" placeholder=\\"placeholder\\" search=\\"original_search or search\\"/>\\n                                            </div>\\n                                            <!-- Mobile Search button -->\\n                                            <t t-call=\\"website.website_search_box_input\\" search_type.f=\\"products\\" _simple_button_layout=\\"True\\" _simple_button_classes.f=\\"d-inline-block d-sm-none me-auto btn-{{navClass}}\\"/>\\n                                        </t>\\n                                        <t t-set=\\"show_product_controls_header\\" t-value=\\"hasPricelistDropdown or is_view_active('website_sale.sort') or wsale_has_filters_btn\\"/>\\n                                        <div t-attf-class=\\"{{'d-lg-none' if not show_product_controls_header else ''}} o_wsale_products_header_dropdown_wrap d-flex gap-3\\">\\n                                            <t t-if=\\"is_view_active('website_sale.sort')\\" t-call=\\"website_sale.sort\\"/>\\n                                            <button t-if=\\"wsale_has_filters_btn\\" t-attf-class=\\"btn btn-{{navClass}} position-relative {{not wsale_has_filters_btn_lg and 'd-lg-none'}} {{not is_view_active('website_sale.search') and 'ms-auto'}} text-nowrap\\" title=\\"Filters\\" data-bs-toggle=\\"offcanvas\\" data-bs-target=\\"#o_wsale_offcanvas\\">\\n                                                <i class=\\"oi\\" data-icon=\\"tune\\" role=\\"img\\"/>\\n                                                <small t-attf-class=\\"ms-1 {{(hasPricelistDropdown and is_view_active('website_sale.search') and is_view_active('website_sale.sort')) and 'd-none d-md-inline-block'}}\\">Filters</small>\\n                                                <span t-if=\\"isFilteringByPrice or attrib_set or tags\\" t-attf-class=\\"position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1\\">\\n                                                    <span class=\\"visually-hidden\\">filters active</span>\\n                                                </span>\\n                                            </button>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div t-if=\\"original_search and products\\" class=\\"alert alert-warning mt8\\">\\n                                    No results found for '<span t-out=\\"original_search\\"/>'. Showing results for '<span t-out=\\"search\\"/>'.\\n                                </div>\\n                            </header>\\n\\n                            <div t-if=\\"products\\" class=\\"o_wsale_products_grid_table_wrapper\\">\\n                                <t t-set=\\"grid_md_allow_custom_cols\\" t-value=\\"hasLeftColumn\\"/>\\n                                <t t-set=\\"grid_md_use_3col\\" t-value=\\"(not hasLeftColumn and ppr == 4) or (opt_wsale_fullwidth and ppr &gt; 3)\\"/>\\n\\n                                <section id=\\"o_wsale_products_grid\\" t-attf-class=\\"o_wsale_products_grid_table grid                                         {{grid_md_allow_custom_cols and 'o_wsale_products_grid_table_md'}}                                         {{website.shop_opt_products_design_classes}}\\" t-attf-style=\\"--o-wsale-ppr: {{ppr}}; --o-wsale-ppg: {{ppg}}; --o-wsale-products-grid-gap: {{gap}};\\" t-att-data-name=\\"grid_block_name\\">\\n                                    <t t-foreach=\\"bins\\" t-as=\\"tr_product\\">\\n                                        <t t-foreach=\\"tr_product\\" t-as=\\"td_product\\">\\n                                            <t t-if=\\"td_product\\">\\n                                                <t t-set=\\"col_height\\" t-value=\\"td_product['y']\\"/>\\n                                                <t t-set=\\"col_width\\" t-value=\\"12 // ppr * td_product['x']\\"/>\\n                                                <t t-set=\\"col_class\\" t-valuef=\\"g-col-6\\"/>\\n                                                <t t-set=\\"col_class_lg\\" t-value=\\"'g-col-lg-' + str(col_width)\\"/>\\n                                                <t t-set=\\"col_class_md\\" t-value=\\"grid_md_allow_custom_cols and ('g-col-md-' + str(col_width)) or grid_md_use_3col and 'g-col-md-4' or 'g-col-md-6'\\"/>\\n                                                <t t-set=\\"col_is_stretched\\" t-value=\\"(td_product['x'] &gt;= td_product['y'] * 2)\\"/>\\n                                                <t t-set=\\"col_is_custom_portrait\\" t-value=\\"not col_is_stretched and (col_height &gt; td_product['x'])\\"/>\\n                                                <t t-set=\\"product\\" t-value=\\"td_product['product']\\"/>\\n                                                <t t-set=\\"product_variant\\" t-value=\\"product_variants[product]\\"/>\\n                                                <t t-set=\\"template_price_vals\\" t-value=\\"get_product_prices(product)\\"/>\\n                                                <t t-set=\\"ribbon\\" t-value=\\"product._get_ribbon(                                                         price_vals=template_price_vals,                                                         auto_assign_ribbons=auto_assign_ribbons,                                                     )\\"/>\\n                                                <div t-attf-class=\\"oe_product {{col_is_custom_portrait and 'oe_product_custom_portrait'}} {{col_class}} {{col_class_md}} {{col_class_lg}} {{col_is_stretched and 'oe_product_size_stretch'}}\\" t-attf-style=\\"--o-wsale-products-grid-product-col-height: {{col_height}};\\" t-att-data-colspan=\\"td_product['x'] != 1 and td_product['x']\\" t-att-data-rowspan=\\"td_product['y'] != 1 and td_product['y']\\" t-att-data-name=\\"product_block_name\\">\\n                                                    <div t-attf-class=\\"o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}\\">\\n                                                        <t t-call=\\"website_sale.products_item\\" design_field=\\"website.shop_opt_products_design_classes\\" product_href=\\"product._get_product_url(product_query_params, grouped_attributes_values)\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                        </t>\\n                                    </t>\\n                                </section>\\n                            </div>\\n                            <div t-else=\\"\\" class=\\"o_wsale_empty_products_grid text-center mt128 mb256\\">\\n                                <t groups=\\"base.group_public\\">\\n                                    <t t-if=\\"not search\\">\\n                                        <div class=\\"mt-5 mb-3\\">\\n                                            <t t-call=\\"website.empty_search_svg\\"/>\\n                                        </div>\\n                                        <h3 class=\\"mt8\\" style=\\"text-align: center;\\">\\n                                            No results\\n                                        </h3>\\n                                        <p style=\\"text-align: center;\\">\\n                                            Try to refine your search criteria.\\n                                        </p>\\n                                    </t>\\n                                    <t t-else=\\"\\">\\n                                        <div class=\\"mt-5 mb-3\\">\\n                                            <t t-call=\\"website.empty_search_svg\\"/>\\n                                        </div>\\n                                        <h3 class=\\"mt8\\" style=\\"text-align: center;\\">No results</h3>\\n                                        <p style=\\"text-align: center;\\">\\n                                            No results for \\"<strong t-out=\\"search\\"/>\\"<t t-if=\\"category\\"> in category \\"<strong t-out=\\"category.display_name\\"/>\\"</t>.\\n                                        </p>\\n                                        <p style=\\"text-align: center;\\">\\n                                            <a t-if=\\"category\\" t-att-href=\\"keep(shop_path, search=search, **reset_filters)\\" t-attf-title=\\"Search {{search}} globally\\" class=\\"d-block pb-5\\">\\n                                                Search globally\\n                                            </a>\\n                                        </p>\\n                                    </t>\\n                                </t>\\n                                <t t-ignore=\\"true\\" groups=\\"sales_team.group_sale_manager\\">\\n                                    <t t-call=\\"website_sale.shop_page_empty_screen\\"/>\\n                                    <h2 class=\\"h4-fs mt-md-4\\">\\n                                        Create your first product\\n                                    </h2>\\n                                    <div>\\n                                        <a name=\\"products_manager_button\\" href=\\"/odoo/action-website_sale.product_template_action_website\\" class=\\"btn btn-primary d-md-none mb-3\\">\\n                                            Go to Products Manager\\n                                        </a>\\n                                    </div>\\n                                </t>\\n                            </div>\\n                            <div id=\\"o_wsale_pager\\" t-attf-class=\\"products_pager d-flex justify-content-center {{opt_wsale_design_grid and 'py-4' or 'py-5 pb-4'}}\\">\\n                                <t t-call=\\"website.pager\\"/>\\n                            </div>\\n                            <t t-if=\\"category\\">\\n                                <t t-set=\\"footer_editor_message\\">\\n                                    Drag blocks here to customize the footer of\\n                                    the \\"<t t-out=\\"category.name\\"/>\\" category\\n                                </t>\\n                                <div class=\\"mb16\\" id=\\"category_footer\\" t-att-data-editor-message=\\"footer_editor_message\\" t-field=\\"category.website_footer\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n\\n                    <t t-call=\\"website_sale.o_wsale_offcanvas\\"/>\\n                </div>\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_2\\"/>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Products" t-name="website_sale.products">\n        <t t-set="website_sale_sortable" t-value="website._get_product_sort_mapping()"/>\n        <t t-call="website.layout" additional_title="category.name" website_sale_sortable="website_sale_sortable">\n            <t t-set="grid_block_name">Grid</t>\n            <t t-set="product_block_name">Product</t>\n\n            <!-- Qweb variable defining the class suffix for navbar items.\n                 Change accordingly to the derired visual result (eg. `primary`, `dark`...)-->\n            <t t-set="navClass" t-valuef="light"/>\n\n            <!-- Check for active options: the stored value may be used in sub-templates too  -->\n            <t t-set="opt_wsale_fullwidth" t-value="website.shop_page_container == 'fluid'"/>\n            <t t-set="opt_wsale_categories" t-value="is_view_active('website_sale.products_categories')"/>\n            <t t-set="opt_wsale_attributes" t-value="is_view_active('website_sale.products_attributes')"/>\n            <t t-set="opt_wsale_filter_price" t-value="is_view_active('website_sale.filter_products_price')"/>\n            <t t-set="opt_wsale_filter_tags" t-value="is_view_active('website_sale.filter_products_tags')"/>\n            <t t-set="opt_wsale_design_grid" t-value="'o_wsale_products_opt_design_grid' in website.shop_opt_products_design_classes"/>\n\n            <t t-set="opt_wsale_categories_top" t-value="is_view_active('website_sale.products_categories_top')"/>\n            <t t-set="opt_wsale_attributes_top" t-value="is_view_active('website_sale.products_attributes_top')"/>\n            <t t-set="opt_wsale_floating_bar" t-value="is_view_active('website_sale.floating_bar')"/>\n\n            <t t-set="opt_wsale_show_shop_title" t-value="is_view_active('website_sale.products_shop_title')"/>\n            <t t-set="opt_wsale_shop_title_align" t-value="is_view_active('website_sale.products_shop_title_align')"/>\n\n            <t t-set="opt_wsale_show_category_title" t-value="website.show_category_title"/>\n            <t t-set="opt_wsale_show_category_description" t-value="website.show_category_description"/>\n            <t t-set="opt_wsale_category_align" t-value="website.align_category_content"/>\n\n            <t t-set="show_price_filter" t-value="opt_wsale_filter_price and opt_wsale_attributes"/>\n            <t t-set="hasLeftColumn" t-value="                     (opt_wsale_categories and categories)                     or (opt_wsale_attributes and (attributes or all_tags or opt_wsale_filter_price))                     or show_price_filter                     or show_on_sale_filter                     or show_in_stock_filter                 "/>\n\n            <t t-set="isFilteringByPrice" t-if="opt_wsale_filter_price" t-value="float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)"/>\n            <t t-set="isSortingBy" t-value="[sort for sort in website_sale_sortable if sort[0]==request.params.get('order', '')]"/>\n\n            <t t-set="wsale_has_filters_btn" t-value="opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top"/>\n            <t t-set="wsale_has_filters_btn_lg" t-value="opt_wsale_attributes_top"/>\n\n            <div id="wrap" class="o_wsale_products_page">\n                <div class="oe_structure oe_empty oe_structure_not_nearest" id="oe_structure_website_sale_products_1"/>\n                <div id="o_wsale_container" t-attf-class="oe_website_sale                         {{opt_wsale_fullwidth and 'container-fluid o_wsale_page_fluid' or 'o_wsale_page_contained container'}}                         {{opt_wsale_categories_top and 'o_wsale_has_filmstrip'}}                         {{opt_wsale_floating_bar and 'o_wsale_has_floating_bar'}}                         {{hasLeftColumn and 'o_wsale_has_sidebar'}}                         {{editionPreviews and 'o_wsale_edit_preview_enabled'}}                         {{opt_wsale_design_grid and 'o_wsale_uses_grid_design'}}" t-att-data-ppg="ppg" t-att-data-ppr="ppr" t-att-data-default-sort="website.shop_default_sort">\n                    <div class="row o_wsale_products_main_row flex-nowrap">\n                        <aside t-if="hasLeftColumn" id="products_grid_before" class="d-none d-lg-block position-sticky align-self-start col clearfix pt-2">\n                            <t t-call="website_sale.sidebar_dropzone_at_top"/>\n                            <div class="o_wsale_products_grid_before_rail ms-n2 px-lg-2 ps-2 overflow-y-scroll">\n                                <t t-set="is_sidebar_collapsible" t-value="is_view_active('website_sale.products_categories_list_collapsible')"/>\n                                <div t-if="opt_wsale_categories" t-att-class="'products_categories'                                                 + (' accordion accordion-flush' if is_sidebar_collapsible else ' mb-3')">\n                                    <t t-call="website_sale.products_categories_list"/>\n                                </div>\n                                <t t-set="has_active_filters" t-value="(                                         attrib_values                                         or tags                                         or (show_on_sale_filter and on_sale_active)                                         or (show_in_stock_filter and in_stock_active)                                         or (show_price_filter and isFilteringByPrice)                                     )"/>\n                                <div t-attf-class="products_attributes_filters d-empty-none {{opt_wsale_categories and 'border-top'}} {{'pt-3' if not is_sidebar_collapsible else ''}}"/>\n                                <t t-if="show_price_filter" t-call="website_sale.filter_products_price" _classes.f="{{is_sidebar_collapsible and 'accordion accordion-flush'}} {{is_sidebar_collapsible and (opt_wsale_categories or len(attributes) &gt; 0) and 'border-top'}}">\n                                </t>\n                                <div t-if="show_on_sale_filter or show_in_stock_filter" class="d-flex flex-wrap gap-2 py-3 border-top">\n                                    <t t-call="website_sale.ribbon_filter_pills"/>\n                                </div>\n                                <div t-if="has_active_filters" class="border-top py-3 border-bottom">\n                                    <a t-att-href="keep(**reset_filters)" t-attf-class="btn btn-{{navClass}} d-flex align-items-center py-1" title="Clear Filters">\n                                        <small class="mx-auto"><b>Clear Filters</b></small>\n                                        <i class="oi" data-icon="close_small" role="presentation"/>\n                                    </a>\n                                </div>\n                                <t t-call="website_sale.sidebar_dropzone_at_bottom"/>\n                            </div>\n                        </aside>\n                        <div id="products_grid" class="col">\n                            <t t-set="_header_has_content" t-value="category or opt_wsale_categories_top or (not opt_wsale_floating_bar and (opt_wsale_attributes_top or is_view_active('website_sale.search') or is_view_active('website_sale.sort') or hasPricelistDropdown))"/>\n\n                            <header id="o_wsale_products_header" t-att-data-category-id="category.id" t-attf-class="d-flex flex-column gap-2                                     {{_header_has_content and 'pt-4 pb-3' or opt_wsale_design_grid and 'py-3'}}                                     {{category and 'o_wsale_products_header_is_category' or 'o_wsale_products_header_is_shop'}}                                     {{opt_wsale_show_category_title and 'o_wsale_products_header_show_category_title'}}                                     {{opt_wsale_show_category_description and 'o_wsale_products_header_show_category_description'}}                                     {{opt_wsale_category_align and 'o_wsale_products_header_category_center_content'}}                                     {{opt_wsale_show_shop_title and 'o_wsale_products_header_show_shop_title'}}                                     {{opt_wsale_shop_title_align and 'o_wsale_products_header_shop_center_content'}}">\n                                <t t-if="category and not search" t-call="website_sale.products_breadcrumb" _classes.f="w-100 p-0 mb-0 small {{not opt_wsale_show_category_title and 'mb-2 mb-lg-0'}}"/>\n                                <h1 t-if="category or search" t-attf-class="o_wsale_category_title d-flex gap-1 align-items-center mb-0 lh-lg {{search and bool(category) and 'mb-2'}} {{search and 'o_wsale_category_title_is_search base-fs font-sans-serif' or 'fs-3'}}">\n                                    <t t-if="search and category">\n                                        <span class="text-muted">Searching</span>\n                                        <span class="badge text-bg-info fw-normal base-fs">\n                                            <t t-out="search"/>\n                                            <a title="Clear search for this category" t-att-href="keep(search=0, **reset_filters)" class="link-info">\n                                                <i class="oi" data-icon="close_small" role="img"/>\n                                            </a>\n                                        </span>\n                                        <span class="text-muted">in</span>\n                                        <span class="badge text-bg-primary fw-normal base-fs">\n                                            <t t-out="category.name"/>\n                                            <a title="Search globally" t-att-href="keep(shop_path, search=search, **reset_filters)">\n                                                <i class="oi" data-icon="close_small" role="img"/>\n                                            </a>\n                                        </span>\n                                    </t>\n                                    <span t-elif="search">\n                                        <span class="text-muted">Search results for </span>'<strong t-out="search"/>' <small t-if="search_count" class="text-muted"> (<t t-out="search_count"/>)</small>\n                                    </span>\n                                    <t t-elif="category">\n                                        <span t-field="category.name"/>\n                                    </t>\n                                </h1>\n                                <div class="o_wsale_shop_title" t-if="not category and not search">\n                                    <h1 class="h4-fs">\n                                        All products\n                                    </h1>\n                                </div>\n                                <t t-if="category">\n                                    <t t-set="editor_msg">\n                                        Drag blocks here to customize the header of\n                                        the "<t t-out="category.name"/>" category\n                                    </t>\n                                    <div id="category_header" class="o_wsale_category_description" t-att-data-editor-message="editor_msg" t-field="category.website_description"/>\n                                </t>\n                                <t t-else="">\n                                    <t t-set="editor_msg">\n                                        Drag blocks here to customize the Shop page header\n                                    </t>\n                                    <div id="oe_structure_products_header_shop" class="oe_structure oe_empty" t-att-data-editor-message="editor_msg"/>\n                                </t>\n                                <t t-if="opt_wsale_categories_top and category_entries" t-call="website_sale.filmstrip_categories" entries="category_entries"/>\n                                <div t-if="not opt_wsale_floating_bar" class="products_header d-flex gap-1 gap-lg-2 gap-xl-3">\n                                    <div class="o_wsale_products_header_inner d-flex justify-content-between w-100">\n                                        <t t-if="is_view_active('website_sale.search')">\n                                            <!-- Desktop Search button -->\n                                            <div class="o_wsale_products_header_search_form_container d-none d-sm-inline-block flex-grow-1 me-auto">\n                                                <t t-if="category" t-set="placeholder" t-valuef.translate="Search in {{category.name}}"/>\n                                                <t t-call="website_sale.search" placeholder="placeholder" search="original_search or search"/>\n                                            </div>\n                                            <!-- Mobile Search button -->\n                                            <t t-call="website.website_search_box_input" search_type.f="products" _simple_button_layout="True" _simple_button_classes.f="d-inline-block d-sm-none me-auto btn-{{navClass}}"/>\n                                        </t>\n                                        <t t-set="show_product_controls_header" t-value="hasPricelistDropdown or is_view_active('website_sale.sort') or wsale_has_filters_btn"/>\n                                        <div t-attf-class="{{'d-lg-none' if not show_product_controls_header else ''}} o_wsale_products_header_dropdown_wrap d-flex gap-3">\n                                            <t t-if="is_view_active('website_sale.sort')" t-call="website_sale.sort"/>\n                                            <button t-if="wsale_has_filters_btn" t-attf-class="btn btn-{{navClass}} position-relative {{not wsale_has_filters_btn_lg and 'd-lg-none'}} {{not is_view_active('website_sale.search') and 'ms-auto'}} text-nowrap" title="Filters" data-bs-toggle="offcanvas" data-bs-target="#o_wsale_offcanvas">\n                                                <i class="oi" data-icon="tune" role="img"/>\n                                                <small t-attf-class="ms-1 {{(hasPricelistDropdown and is_view_active('website_sale.search') and is_view_active('website_sale.sort')) and 'd-none d-md-inline-block'}}">Filters</small>\n                                                <span t-if="isFilteringByPrice or attrib_set or tags" t-attf-class="position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1">\n                                                    <span class="visually-hidden">filters active</span>\n                                                </span>\n                                            </button>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div t-if="original_search and products" class="alert alert-warning mt8">\n                                    No results found for '<span t-out="original_search"/>'. Showing results for '<span t-out="search"/>'.\n                                </div>\n                            </header>\n\n                            <div t-if="products" class="o_wsale_products_grid_table_wrapper">\n                                <t t-set="grid_md_allow_custom_cols" t-value="hasLeftColumn"/>\n                                <t t-set="grid_md_use_3col" t-value="(not hasLeftColumn and ppr == 4) or (opt_wsale_fullwidth and ppr &gt; 3)"/>\n\n                                <section id="o_wsale_products_grid" t-attf-class="o_wsale_products_grid_table grid                                         {{grid_md_allow_custom_cols and 'o_wsale_products_grid_table_md'}}                                         {{website.shop_opt_products_design_classes}}" t-attf-style="--o-wsale-ppr: {{ppr}}; --o-wsale-ppg: {{ppg}}; --o-wsale-products-grid-gap: {{gap}};" t-att-data-name="grid_block_name">\n                                    <t t-foreach="bins" t-as="tr_product">\n                                        <t t-foreach="tr_product" t-as="td_product">\n                                            <t t-if="td_product">\n                                                <t t-set="col_height" t-value="td_product['y']"/>\n                                                <t t-set="col_width" t-value="12 // ppr * td_product['x']"/>\n                                                <t t-set="col_class" t-valuef="g-col-6"/>\n                                                <t t-set="col_class_lg" t-value="'g-col-lg-' + str(col_width)"/>\n                                                <t t-set="col_class_md" t-value="grid_md_allow_custom_cols and ('g-col-md-' + str(col_width)) or grid_md_use_3col and 'g-col-md-4' or 'g-col-md-6'"/>\n                                                <t t-set="col_is_stretched" t-value="(td_product['x'] &gt;= td_product['y'] * 2)"/>\n                                                <t t-set="col_is_custom_portrait" t-value="not col_is_stretched and (col_height &gt; td_product['x'])"/>\n                                                <t t-set="product" t-value="td_product['product']"/>\n                                                <t t-set="product_variant" t-value="product_variants[product]"/>\n                                                <t t-set="template_price_vals" t-value="get_product_prices(product)"/>\n                                                <t t-set="ribbon" t-value="product._get_ribbon(                                                         price_vals=template_price_vals,                                                         auto_assign_ribbons=auto_assign_ribbons,                                                     )"/>\n                                                <div t-attf-class="oe_product {{col_is_custom_portrait and 'oe_product_custom_portrait'}} {{col_class}} {{col_class_md}} {{col_class_lg}} {{col_is_stretched and 'oe_product_size_stretch'}}" t-attf-style="--o-wsale-products-grid-product-col-height: {{col_height}};" t-att-data-colspan="td_product['x'] != 1 and td_product['x']" t-att-data-rowspan="td_product['y'] != 1 and td_product['y']" t-att-data-name="product_block_name">\n                                                    <div t-attf-class="o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}">\n                                                        <t t-call="website_sale.products_item" design_field="website.shop_opt_products_design_classes" product_href="product._get_product_url(product_query_params, grouped_attributes_values)"/>\n                                                    </div>\n                                                </div>\n                                            </t>\n                                        </t>\n                                    </t>\n                                </section>\n                            </div>\n                            <div t-else="" class="o_wsale_empty_products_grid text-center mt128 mb256">\n                                <t groups="base.group_public">\n                                    <t t-if="not search">\n                                        <div class="mt-5 mb-3">\n                                            <t t-call="website.empty_search_svg"/>\n               