                               <t t-set=\\"product_actions\\">\\n                                        <div class=\\"o_wsale_product_action_row\\">\\n                                            <a t-if=\\"combination_info['prevent_sale']\\" t-att-href=\\"website._get_contact_us_url(combination_info['display_name'])\\" class=\\"o_wsale_product_btn_primary btn btn-primary\\">\\n                                                <span class=\\"d-inline-flex align-items-baseline\\">\\n                                                    <i class=\\"oi oi-fw oi-filled o_not-animable\\" data-icon=\\"mail\\" role=\\"presentation\\"/>\\n                                                    <span class=\\"o_label small ms-1\\">\\n                                                        Contact Us\\n                                                    </span>\\n                                                </span>\\n                                            </a>\\n                                            <button t-else=\\"\\" name=\\"add_to_cart\\" class=\\"o_wsale_product_btn_primary btn btn-primary\\" t-att-data-product-id=\\"product_variant.id\\" t-att-data-product-template-id=\\"product.id\\" t-att-data-product-type=\\"product.type\\" t-att-data-ptav-ids=\\"json.dumps(product_variant.product_template_attribute_value_ids.ids)\\" t-att-data-show-quantity=\\"is_view_active('website_sale.product_quantity')\\" t-att-disabled=\\"wish.product_id._is_sold_out()\\">\\n                                                <span class=\\"d-inline-flex align-items-baseline\\">\\n                                                    <i class=\\"oi oi-fw o_not-animable\\" data-icon=\\"shopping_cart\\" role=\\"presentation\\"/>\\n                                                    <span class=\\"o_label small ms-1\\">\\n                                                        Add to Cart\\n                                                    </span>\\n                                            