d_ids or pm_sudo"/>\n        <t t-set="inline_form_xml_id" t-value="provider_sudo.inline_form_view_id.xml_id"/>\n        <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-0 p-0" for="o_payment_radio">\n            <div class="form-check d-flex flex-grow-1 flex-wrap mb-0">\n                <div class="d-flex justify-content-between align-items-center gap-2 flex-wrap w-100">\n                    <!-- === Radio button === -->\n                    <input t-attf-id="o_payment_method_{{pm_sudo.id}}" name="o_payment_radio" type="radio" t-att-checked="is_selected" class="form-check-input position-absolute mt-0" data-payment-option-type="payment_method" t-att-data-payment-option-id="pm_sudo.id" t-att-data-payment-method-code="pm_sudo.code" t-att-data-provider-id="provider_sudo.id" t-att-data-provider-code="provider_sudo._get_code()" t-att-data-provider-is-live="provider_sudo.is_live"/>\n                    <div class="d-flex gap-2 flex-grow-1 me-auto">\n                        <!-- === Method label === -->\n                        <label t-out="pm_sudo.name" class="o_payment_option_label mb-0 text-break" t-attf-for="o_payment_method_{{pm_sudo.id}}"/>\n                        <div class="d-flex flex-nowrap gap-2 mt-1">\n                            <!-- === "Unpublished" icon === -->\n                            <t t-if="is_unpublished" t-call="payment.form_icon" icon_name.f="visibility_off" color_name.f="danger" title.translate="Unpublished"/>\n                            <!-- === "Test mode" icon === -->\n                            <t t-if="is_test" t-call="payment.form_icon" icon_name.f="warning" color_name.f="warning" title.translate="Test mode"/>\n                        </div>\n                    </div>\n                    <div class="gap-1 flex-wrap d-flex">\n                        <!-- === Payment method logos === -->\n                        <t t-set="pm_index" t-value="0"/>\n                        <t t-foreach="pms_to_display_sudo"