770	16	\N	1	1	payment.state_header	\N	payment.state_header	qweb	payment/views/portal_templates.xml	primary	\N	{"en_US": "<t t-name=\\"payment.state_header\\">\\n        <!-- Parameters description:\\n            - tx: The transaction whose status must be displayed.\\n        -->\\n        <t t-set=\\"status_message\\" t-value=\\"tx._get_status_message()\\"/>\\n        <t t-if=\\"tx.state == 'draft'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'warning'\\"/>\\n            <t t-set=\\"alert_icon\\" t-value=\\"'warning'\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'pending'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'info'\\"/>\\n            <t t-set=\\"alert_icon\\" t-value=\\"'info'\\"/>\\n            <t t-set=\\"alert_icon_class\\" t-value=\\"'oi-filled'\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'authorized' or tx.state == 'done'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'success'\\"/>\\n            <t t-set=\\"alert_icon\\" t-value=\\"'check'\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'cancel' or tx.state == 'error'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'danger'\\"/>\\n            <t t-set=\\"alert_icon\\" t-value=\\"'warning'\\"/>\\n        </t>\\n\\n        <t t-set=\\"o_payment_status_alert_class\\" t-value=\\"'alert alert-'+ alert_style +' d-flex gap-3'\\"/>\\n        <div t-if=\\"status_message\\" name=\\"o_payment_status_alert\\" t-attf-class=\\"{{o_payment_status_alert_class}}\\">\\n            <div id=\\"o_payment_status_icon\\">\\n                <i t-attf-class=\\"oi {{alert_icon_class}}\\" t-att-data-icon=\\"alert_icon\\"/>\\n            </div>\\n            <div id=\\"o_payment_status_message\\" class=\\"w-100\\">\\n                <t t-out=\\"status_message\\"/>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.state_header">\n        <!-- Parameters description:\n            - tx: The transaction whose status must be displayed.\n        -->\n        <t t-set="status_message" t-value="tx._get_status_message()"/>\n        <t t-if="tx.state == 'draft'">\n            <t t-set="alert_style" t-value="'warning'"/>\n            <t t-set="alert_icon" t-value="'warning'"/>\n        </t>\n        <t t-elif="tx.state == 'pending'">\n            <t t-set="alert_style" t-value="'info'"/>\n            <t t-set="alert_icon" t-value="'info'"/>\n            <t t-set="alert_icon_class" t-value="'oi-filled'"/>\n        </t>\n        <t t-elif="tx.state == 'authorized' or tx.state == 'done'">\n            <t t-set="alert_style" t-value="'success'"/>\n            <t t-set="alert_icon" t-value="'check'"/>\n        </t>\n        <t t-elif="tx.state == 'cancel' or tx.state == 'error'">\n            <t t-set="alert_style" t-value="'danger'"/>\n            <t t-set="alert_icon" t-value="'warning'"/>\n        </t>\n\n        <t t-set="o_payment_status_alert_class" t-value="'alert alert-'+ alert_style +' d-flex gap-3'"/>\n        <div t-if="status_message" name="o_payment_status_alert" t-attf-class="{{o_payment_status_alert_class}}">\n            <div id="o_payment_status_icon">\n                <i t-attf-class="oi {{alert_icon_class}}" t-att-data-icon="alert_icon"/>\n            </div>\n            <div id="o_payment_status_message" class="w-100">\n                <t t-out="status_message"/>\n            </div>\n        </div>\n    </t>\n\n	\N	f	t	2026-10-05 09:56:21.828814	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
