          </div>\n                            <div t-if="o.amount">\n                                Payment Amount: <span t-field="o.amount" t-options="{'widget': 'monetary', 'display_currency': o.currency_id}">50 USD</span>\n                            </div>\n                            <div name="payment_method" t-if="values['display_payment_method'] and o.payment_method_line_id">\n                                Payment Method: <span t-field="o.payment_method_line_id.name">Credit card</span>\n                            </div>\n                            <div t-if="o.memo">\n                                Memo: <span t-field="o.memo">Sample Memo</span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                </div>\n\n                <div class="oe_structure"/>\n                <table name="invoices" t-if="values['display_invoices']" class="table table-borderless">\n                    <t t-set="invoices" t-value="o.reconciled_invoice_ids or o.reconciled_bill_ids"/>\n                    <t t-set="inv_to_rows" t-value="{inv.id: inv._get_reconciled_invoices_partials_for_receipt() for inv in invoices}"/>\n                    <!-- Check if invoices include different currencies -->\n                    <t t-set="otherCurrency" t-value="any(row['currency_payment'] and inv.currency_id != row['currency_payment'] for inv in invoices for row in inv_to_rows[inv.id])"/>\n                    <thead>\n                        <tr>\n                            <th><span>Invoice Date</span></th>\n                            <th><span>Invoice Number</span></th>\n                            <th><span>Reference</span></th>\n                            <!-- Add a column if there are different currencies -->\n                            <th t-if="otherCurrency" class="text-end"><span>Amount In Currency</span></th>\n                            <th class="text-end"><span>Amount</span></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <t t-foreach="invoices" t-as="inv">\n                            <!-- MOVE -->\n                            <t t-if="inv.move_type != 'entry'">\n                                <tr>\n                                    <td><span t-field="inv.invoice_date">2023-01-01</span></td>\n                                    <td><span t-field="inv.name">INV001</span></td>\n                                    <td><span t-field="inv.ref" data-oe-demo="Sample Ref"/></td>\n                                    <td t-if="otherCurrency"/>\n                                    <td class="text-end"><span t-field="inv.amount_total">100.00 USD</span></td>\n                                </tr>\n                                <!-- PAYMENTS/REVERSALS -->\n                                <tr t-foreach="inv_to_rows[inv.id]" t-as="row">\n                                    <td><span t-if="row['date']" t-out="row['date']" t-options="{'widget': 'date'}">2023-01-05</span></td>\n                                    <td><span t-out="row['name']">PAY001</span></td>\n                                    <td><span t-if="row['ref']" t-out="row['ref']" data-oe-demo="Payment Ref"/></td>\n                                    <!-- Fill the column "Amount In Currency" only if necessary -->\n                                    <td t-if="otherCurrency" class="text-end"><span t-if="row['currency_payment'] and row['currency_payment'] != row['currency_invoice']" t-out="row['amount_payment']" t-options="{'widget': 'monetary', 'display_currency': row['currency_payment']}">50.00 EUR</span></td>\n                                    <td class="text-end"><span t-out="row['amount_invoice']" t-options="{'widget': 'monetary', 'display_currency': row['currency_invoice']}">25.00 USD</span></td>\n                                </tr>\n                                <!-- BALANCE -->\n                                <tr>\n                                    <td/>\n                                    <td><strong>Due Amount for <span t-field="inv.name">INV001</span></strong></td>\n                                    <td/>\n                                    <td t-if="otherCurrency"/>\n                                    <td class="text-end"><strong><span t-field="inv.amount_residual">25.0 USD</span></strong></td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n            </div>\n            <div class="oe_structure"/>\n        </t>\n    </t>\n\n    	\N	f	t	2026-10-05 09:56:23.384265	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
