\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                    <strong>Delivery address</strong>\\n                                                    <div>Presence depends on the operation category.</div>\\n                                                </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-5 offset-1\\" name=\\"div_customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\\">\\n                                    <div>\\n                                        <span><strong>Customer Address:</strong></span>\\n                                    </div>\\n                                    <div name=\\"partner_header\\">\\n                                        <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;] if show_full_address else [&quot;name&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                <strong>Recipient address</strong>\\n                                                <div>Presence depends on the operation category.</div>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"oe_structure\\"/>\\n                            <div class=\\"mt32 mb32 o_stock_report_header_row\\">\\n                                <div t-if=\\"o.origin\\" name=\\"div_origin\\">\\n                                    <strong>Order:</strong>\\n                                    <p t-field=\\"o.origin\\">S0001</p>\\n                                </div>\\n                                <div name=\\"div_warehouse\\">\\n                                    <strong>Warehouse:</strong>\\n                                    <div t-if=\\"o.picking_type_id.warehouse_id.partner_id\\" t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                    <div t-else=\\"\\" t-field=\\"o.picking_type_id.warehouse_id.name\\"/>\\n                                    </div>\\n                                <div t-if=\\"o.picking_type_id.code == 'internal' and o.partner_id\\" class=\\"col\\" name=\\"div_contact\\">\\n                                    <strong>Contact</strong>\\n                                    <div t-field=\\"o.partner_id\\" class=\\"m-0\\"/>\\n                                </div>\\n                                <div name=\\"div_state\\">\\n                                    <strong>Status:</strong>\\n                                    <p t-field=\\"o.state\\">Draft</p>\\n                                </div>\\n                                <div t-if=\\"o.user_id\\" name=\\"div_operator\\">\\n                                    <strong>Operator:</strong>\\n                                    <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                                </div>\\n                                <div name=\\"div_picking_date\\">\\n                                    <t t-if=\\"o.state == 'done' and o.date_done\\">\\n                                        <strong>Done Date:</strong>\\n                                        <p t-field=\\"o.date_done\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                    <t t-elif=\\"o.state != 'done' and o.scheduled_date\\">\\n                                        <strong>Scheduled Date:</strong>\\n                                        <p t-field=\\"o.scheduled_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                </div>\\n                                <div name=\\"div_warn\\" t-if=\\"o.picking_warning_text\\">\\n                                    <strong>Instructions:</strong>\\n                                    <div t-field=\\"o.picking_warning_text\\"/>\\n                                </div>\\n                                <div name=\\"div_vendor\\" t-if=\\"o.picking_type_id.code=='incoming' and o.partner_id\\">\\n                                    <strong>From:</strong>\\n                                    <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                            <!-- In this step, we loop over every move of the picking and do the following\\n                                1. We add the barcode column if any of the products has a barcode or if we have a tracked move\\n                                2. We add From/To columns according to the type of the picking\\n                                3. If a move has multiple move lines, we add a header line summarizing the move,\\n                                then we then loop over indvidual move lines and print a breakdown of them\\n                                4. If a move contains only one move line, the move is summarized in the heading only\\n                            -->\\n                            <table class=\\"table o_main_table\\" t-if=\\"o.move_line_ids and o.move_ids.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\" style=\\"table-layout: fixed; width: 100%\\">\\n                                <t t-set=\\"picking_has_barcode\\" t-value=\\"any(move_line.product_id and move_line.product_id.barcode for move_line in o.move_line_ids)\\"/>\\n                                <t t-set=\\"picking_has_serial_number\\" t-value=\\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\\" groups=\\"stock.group_production_lot\\"/>\\n                                <t t-set=\\"barcode_col_exists\\" t-value=\\"picking_has_barcode or picking_has_serial_number\\"/>\\n                                <t t-set=\\"from_col_exists\\" t-value=\\"o.picking_type_id.code != 'incoming'\\"/>\\n                                <t t-set=\\"to_col_exists\\" t-value=\\"o.picking_type_id.code != 'outgoing'\\"/>\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_product\\" class=\\"text-start\\">\\n                                            <strong>Product</strong>\\n                                        </th>\\n                                        <th name=\\"th_quantity\\" class=\\"text-end\\">\\n                                            <strong>Quantity</strong>\\n                                        </th>\\n                                        <th name=\\"th_from\\" class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>From</strong>\\n                                        </th>\\n                                        <th name=\\"th_to\\" class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>To</strong>\\n                                        </th>\\n                                        <th name=\\"th_barcode\\" class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                            <strong>Barcode</strong>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-foreach=\\"o.move_ids.filtered(lambda m: m.quantity and any(not ml.is_entire_pack for ml in m.move_line_ids)).sorted(key=lambda                                                   move: (move.move_line_ids and move.move_line_ids[0].location_id.complete_name,                                                   move.move_line_ids and move.move_line_ids[0].location_dest_id.complete_name))\\" t-as=\\"move\\">\\n                                        <t t-set=\\"move_lines_without_entire_pack\\" t-value=\\"move.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\"/>\\n                                        <!-- This flag is true if there are multiple move lines in a move, or if there is at least one tracked move line -->\\n                                        <t t-set=\\"move_has_multiple_lines\\" t-value=\\"len(move.move_line_ids) &gt; 1 or any(move_line.lot_id or move_line.lot_name for move_line in move_lines_without_entire_pack)\\"/>\\n                                        <tr>\\n                                            <td class=\\"text-start\\">\\n                                                <span t-field=\\"move.product_id.display_name\\">Customizable Desk</span><br/>\\n                                                <span t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name\\">\\n                                                    <span t-out=\\"move.description_picking\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                                </span>\\n                                            </td>\\n                                            <td class=\\"o_td_quantity text-end\\">\\n                                                <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                                <span t-field=\\"move.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                                <span t-if=\\"move.packaging_uom_id and move.packaging_uom_id != move.uom_id\\">\\n                                                    (<span t-field=\\"move.packaging_uom_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"move.packaging_uom_id.name\\"/>)\\n                                                </span>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].package_id\\">Package A</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].result_package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].result_package_id\\">Package B</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- We add the barcode column if any of the products has a barcode or if we have a tracked move -->\\n                                            <td class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                                <span t-if=\\"move.product_id and move.product_id.barcode\\">\\n                                                    <div t-field=\\"move.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (product barcode)\\n                                                        </div>\\n                                                    </div>\\n                                                </span>\\n                                            </td>\\n                                        </tr>\\n                                        <!-- If a move has multiple move lines, we then loop over them and print a breakdown -->\\n                                        <t t-foreach=\\"move_lines_without_entire_pack.sorted(key=lambda ml: (ml.location_id.complete_name,                                                       ml.location_dest_id.complete_name))\\" t-as=\\"line\\" t-if=\\"move_has_multiple_lines\\">\\n                                            <tr>\\n                                                <td class=\\"text-start\\">\\n                                                    <span style=\\"margin-left: 50px;\\" t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name\\"/>\\n                                                </td>\\n                                                <td class=\\"text-end\\">\\n                                                    <span t-out=\\"format_number(line.quantity)\\">3.00</span>\\n                                                    <span t-field=\\"line.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"line.package_id\\">\\n                                                        <span t-field=\\"line.package_id\\">Package A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"line.result_package_id\\">\\n                                                        <span t-field=\\"line.result_package_id\\">Package A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\" text-center h6\\" t-if=\\"barcode_col_exists\\">\\n                                                    <span t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name or line.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (serial barcode)\\n                                                        </div>\\n                                                    </span>\\n                                                </td>\\n                                            </tr>\\n                                        </t>\\n                                    </t>\\n                                    </tbody>\\n                            </table>\\n                            <div t-if=\\"not (any(ml.is_entire_pack for ml in o.move_line_ids) and o.state in ['assigned', 'done'])\\" class=\\"oe_structure\\"/>\\n                            <table t-else=\\"\\" class=\\"table table-borderless\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Package</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">From</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">To</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-if=\\"o.state != 'done'\\">\\n                                        <tr t-foreach=\\"o.move_line_ids.filtered(lambda ml: ml.is_entire_pack).package_id.outermost_package_id.sorted(key=lambda p: p.name)\\" t-as=\\"package\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (package barcode)\\n                                                    </div>\\n                                                </div>\\n                                                    <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_id\\"/>\\n                                                <span t-field=\\"package.parent_package_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_dest_id\\"/>\\n                                                <span t-field=\\"package.package_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-else=\\"\\">\\n                                        <tr t-foreach=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id and all(ml.is_entire_pack for ml in ph.move_line_ids)).sorted(key=lambda ph: ph.package_id.name)\\" t-as=\\"package_history\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package_history.package_id.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (package barcode)\\n                                                    </div>\\n                                                </div>\\n                                                <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_id\\"/>\\n                                                <span t-field=\\"package_history.parent_orig_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_dest_id\\"/>\\n                                                <span t-field=\\"package_history.parent_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </tbody>\\n                            </table>\\n\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty &gt; x.quantity and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"oi\\" data-icon=\\"warning\\"/>\\n                                All products could not be reserved. Click on the \\"Reserve\\" button to try to reserve products.\\n                            </p>\\n                            <p t-else=\\"\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                            <p t-field=\\"o.note\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                        </div>\\n                        <t t-if=\\"not o_last\\">\\n                            <p style=\\"page-break-after: always;\\"/>\\n                        </t>\\n                    </t>\\n                </div>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking">\n            <t t-call="web.report_layout">\n                <div class="article o_report_layout_standard">\n                    <t t-foreach="docs" t-as="o">\n                        <t t-set="address" t-value="None"/>\n                        <div class="page">\n                            <div class="row justify-content-between">\n                                <div class="col-4">\n                                    <h3 t-field="o.picking_type_id.code"/>\n                                    <h2 t-field="o.name">WH/OUT/00001</h2>\n                                </div>\n                                <div class="col-8" name="right_box">\n                                    <div t-field="o.name" style="display:flex;justify-content:flex-end;display:-webkit-box;-webkit-box-pack:end;" t-options="{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-right:0;'}">\n                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center">\n                                            (document barcode)\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-6" name="div_outgoing_address">\n                                    <div t-if="o.should_print_delivery_address()">\n                                        <strong>Delivery Address:</strong>\n                                        <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                    <strong>Delivery address</strong>\n                                                    <div>Presence depends on the operation category.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-5 offset-1" name="div_customer_address" t-if="o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">\n                                    <div>\n                                        <span><strong>Customer Address:</strong></span>\n                                    </div>\n                                    <div name="partner_header">\n                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;] if show_full_address else [&quot;name&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                <strong>Recipient address</strong>\n                                                <div>Presence depends on the operation category.</div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="oe_structure"/>\n                            <div class="mt32 mb32 o_stock_report_header_row">\n                                <div t-if="o.origin" name="div_origin">\n                                    <strong>Order:</strong>\n                                    <p t-field="o.origin">S0001</p>\n                                </div>\n                                <div name="div_warehouse">\n                                    <strong>Warehouse:</strong>\n                                    <div t-if="o.picking_type_id.warehouse_id.partner_id" t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                    <div t-else="" t-field="o.picking_type_id.warehouse_id.name"/>\n                                    </div>\n                                <div t-if="o.picking_type_id.code == 'internal' and o.partner_id" class="col" name="div_contact">\n                                    <strong>Contact</strong>\n                                    <div t-field="o.partner_id" class="m-0"/>\n                                </div>\n                                <div name="div_state">\n                                    <strong>Status:</strong>\n                                    <p t-field="o.state">Draft</p>\n                                </div>\n                                <div t-if="o.user_id" name="div_operator">\n                                    <strong>Operator:</strong>\n                                    <p t-field="o.user_id">Mitchel Admin</p>\n                                </div>\n                                <div name="div_picking_date">\n                                    <t t-if="o.state == 'done' and o.date_done">\n                                        <strong>Done Date:</strong>\n                                        <p t-field="o.date_done" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-09-24</p>\n                                    </t>\n                                    <t t-elif="o.state != 'done' and o.scheduled_date">\n                                        <strong>Scheduled Date:</strong>\n                                        <p t-field="o.scheduled_date" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-09-24</p>\n                                    </t>\n                                </div>\n                                <div name="div_warn" t-if="o.picking_warning_text">\n                                    <strong>Instructions:</strong>\n                                    <div t-field="o.picking_warning_text"/>\n                                </div>\n                                <div name="div_vendor" t-if="o.picking_type_id.code=='incoming' and o.partner_id">\n                                    <strong>From:</strong>\n                                    <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                    </div>\n                                </div>\n                            </div>\n                            <t t-set="format_number" t-value="lambda x: int(x) if x == int(x) else x"/>\n                            <!-- In this step, we loop over every move of the picking and do the following\n                                1. We add the barcode column if any of the products has a barcode or if we have a tracked move\n                                2. We add From/To columns according to the type of the picking\n                                3. If a move has multiple move lines, we add a header line summarizing the move,\n                                then we then loop over indvidual move lines and print a breakdown of them\n                                4. If a move contains only one move line, the move is summarized in the heading only\n                            -->\n                            <table class="table o_main_table" t-if="o.move_line_ids and o.move_ids.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)" style="table-layout: fixed; width: 100%">\n                                <t t-set="picking_has_barcode" t-value="any(move_line.product_id and move_line.product_id.barcode for move_line in o.move_line_ids)"/>\n                                <t t-set="picking_has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>\n                                <t t-set="barcode_col_exists" t-value="picking_has_barcode or picking_has_serial_number"/>\n                                <t t-set="from_col_exists" t-value="o.picking_type_id.code != 'incoming'"/>\n                                <t t-set="to_col_exists" t-value="o.picking_type_id.code != 'outgoing'"/>\n                                <thead>\n                                    <tr>\n                                        <th name="th_product" class="text-start">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th name="th_quantity" class="text-end">\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name="th_from" class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name="th_to" class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name="th_barcode" class="text-center" t-if="barcode_col_exists">\n                                            <strong>Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <t t-foreach="o.move_ids.filtered(lambda m: m.quantity and any(not ml.is_entire_pack for ml in m.move_line_ids)).sorted(key=lambda                                                   move: (move.move_line_ids and move.move_line_ids[0].location_id.complete_name,                                                   move.move_line_ids and move.move_line_ids[0].location_dest_id.complete_name))" t-as="move">\n                                        <t t-set="move_lines_without_entire_pack" t-value="move.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)"/>\n                                        <!-- This flag is true if there are multiple move lines in a move, or if there is at least one tracked move line -->\n                                        <t t-set="move_has_multiple_lines" t-value="len(move.move_line_ids) &gt; 1 or any(move_line.lot_id or move_line.lot_name for move_line in move_lines_without_entire_pack)"/>\n                                        <tr>\n                                            <td class="text-start">\n                                                <span t-field="move.product_id.display_name">Customizable Desk</span><br/>\n                                                <span t-if="move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name">\n                                                    <span t-out="move.description_picking" t-options="{'widget': 'text'}">Description on transfer</span>\n                                                </span>\n                                            </td>\n                                            <td class="o_td_quantity text-end">\n                                                <span t-out="format_number(move.quantity)" class="text-nowrap">3.00</span>\n                                                <span t-field="move.uom_id" groups="uom.group_uom">units</span>\n                                                <span t-if="move.packaging_uom_id and move.packaging_uom_id != move.uom_id">\n                                                    (<span t-field="move.packaging_uom_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move.packaging_uom_id.name"/>)\n                                                </span>\n                                            </td>\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\n                                            <td class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                                <div t-if="move.move_line_ids and not move_has_multiple_lines">\n                                                    <span t-field="move.move_line_ids[0].location_id.display_name">WH/Stock</span>\n                                                    <t t-if="move.move_line_ids[0].package_id">\n                                                        <span t-field="move.move_line_ids[0].package_id">Package A</span>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\n                                            <td class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                                <div t-if="move.move_line_ids and not move_has_multiple_lines">\n                                                    <span t-field="move.move_line_ids[0].location_dest_id.display_name">WH/Outgoing</span>\n                                                    <t t-if="move.move_line_ids[0].result_package_id">\n                                                        <span t-field="move.move_line_ids[0].result_package_id">Package B</span>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <!-- We add the barcode column if any of the products has a barcode or if we have a tracked move -->\n                                            <td class="text-center" t-if="barcode_col_exists">\n                                                <span t-if="move.product_id and move.product_id.barcode">\n                                                    <div t-field="move.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}">\n                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                            (product barcode)\n                                                        </div>\n                                                    </div>\n                                                </span>\n                                            </td>\n                                        </tr>\n                                        <!-- If a move has multiple move lines, we then loop over them and print a breakdown -->\n                                        <t t-foreach="move_lines_without_entire_pack.sorted(key=lambda ml: (ml.location_id.complete_name,                                                       ml.location_dest_id.complete_name))" t-as="line" t-if="move_has_multiple_lines">\n                                            <tr>\n                                                <td class="text-start">\n                                                    <span style="margin-left: 50px;" t-if="line.lot_id or line.lot_name" t-out="line.lot_id.name"/>\n                                                </td>\n                                                <td class="text-end">\n                                                    <span t-out="format_number(line.quantity)">3.00</span>\n                                                    <span t-field="line.uom_id" groups="uom.group_uom">units</span>\n                                                </td>\n                                                <td class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                                    <span t-field="line.location_id.display_name">WH/Stock</span>\n                                                    <t t-if="line.package_id">\n                                                        <span t-field="line.package_id">Package A</span>\n                                                    </t>\n                                                </td>\n                                                <td class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                                    <span t-field="line.location_dest_id.display_name">WH/Outgoing</span>\n                                                    <t t-if="line.result_package_id">\n                                                        <span t-field="line.result_package_id">Package A</span>\n                                                    </t>\n                                                </td>\n                                                <td class=" text-center h6" t-if="barcode_col_exists">\n                                                    <span t-if="line.lot_id or line.lot_name" t-out="line.lot_id.name or line.lot_name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}">\n                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                            (serial barcode)\n                                                        </div>\n                                                    </span>\n                                                </td>\n                                            </tr>\n                                        </t>\n                                    </t>\n                                    </tbody>\n                            </table>\n                            <div t-if="not (any(ml.is_entire_pack for ml in o.move_line_ids) and o.state in ['assigned', 'done'])" class="oe_structure"/>\n                            <table t-else="" class="table table-borderless">\n                                <thead>\n                                    <tr>\n                                        <th name="th_package">Package</th>\n                                        <th name="th_pko_from" t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">From</th>\n                                        <th name="th_pki_from" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <t t-if="o.state != 'done'">\n                                        <tr t-foreach="o.move_line_ids.filtered(lambda ml: ml.is_entire_pack).package_id.outermost_package_id.sorted(key=lambda p: p.name)" t-as="package">\n                                            <td name="td_pk_barcode">\n                                                <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>\n                                                <div t-field="package.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}">\n                                                    <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">\n                                                        (package barcode)\n                                                    </div>\n                                                </div>\n                                                    <br/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package.location_id"/>\n                                                <span t-field="package.parent_package_id"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package.location_dest_id"/>\n                                                <span t-field="package.package_dest_id"/>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                    <t t-else="">\n                                        <tr t-foreach="o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id and all(ml.is_entire_pack for ml in ph.move_line_ids)).sorted(key=lambda ph: ph.package_id.name)" t-as="package_history">\n                                            <td name="td_pk_barcode">\n                                                <t t-set="package" t-value="package_history.package_id.with_context(picking_id=o.id)"/>\n                                                <div t-field="package.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}">\n                                                    <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">\n                                                        (package barcode)\n                                                    </div>\n                                                </div>\n                                                <br/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package_history.location_id"/>\n                                                <span t-field="package_history.parent_orig_id"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package_history.location_dest_id"/>\n                                                <span t-field="package_history.parent_dest_id"/>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                </tbody>\n                            </table>\n\n                            <t t-set="no_reserved_product" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty &gt; x.quantity and x.move_line_ids and x.state!='done')"/>\n                            <p t-if="o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product"><i class="oi" data-icon="warning"/>\n                                All products could not be reserved. Click on the "Reserve" button to try to reserve products.\n                            </p>\n                            <p t-else=""/>\n                            <div class="oe_structure"/>\n                            <p t-field="o.note"/>\n                            <div class="oe_structure"/>\n                        </div>\n                        <t t-if="not o_last">\n                            <p style="page-break-after: always;"/>\n                        </t>\n                    </t>\n                </div>\n            </t>\n        </t>\n        	\N	f	t	2026-10-05 09:56:31.551916	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
1014	16	\N	1	1	picking_type_barcode_4x7_label	\N	stock.picking_type_barcode_4x7_label	qweb	stock/report/report_stockpicking_operations.xml	primary	\N	{"en_US": "<t t-name=\\"stock.picking_type_barcode_4x7_label\\">\\n            <td t-att-style=\\"label['invisible'] and 'visibility:hidden;'\\">\\n                <div class=\\"o_label_full o_label_4x7\\">\\n                    <t t-if=\\"not label.get('invisible')\\">\\n                        <t t-call=\\"product.report_label_contour_marks\\"/>\\n                        <div class=\\"o_label_centering_table\\">\\n                            <div class=\\"o_label_centered_content\\">\\n                                <div class=\\"o_label_name\\" t-out=\\"label['name']\\"/>\\n                                <div class=\\"o_label_content\\">\\n                                    <div class=\\"o_label_barcode_block\\">\\n                                        <t t-call=\\"product.report_label_barcode\\" barcode_size=\\"'width:100%;height:8mm'\\"/>\\n                                        <div class=\\"o_label_barcode_text\\" t-out=\\"label['barcode_text']\\"/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </td>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.picking_type_barcode_4x7_label">\n            <td t-att-style="label['invisible'] and 'visibility:hidden;'">\n                <div class="o_label_full o_label_4x7">\n                    <t t-if="not label.get('invisible')">\n                        <t t-call="product.report_label_contour_marks"/>\n                        <div class="o_label_centering_table">\n                            <div class="o_label_centered_content">\n                                <div class="o_label_name" t-out="label['name']"/>\n                                <div class="o_label_content">\n                                    <div class="o_label_barcode_block">\n                                        <t t-call="product.report_label_barcode" barcode_size="'width:100%;height:8mm'"/>\n                                        <div class="o_label_barcode_text" t-out="label['barcode_text']"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </td>\n        </t>\n    	\N	f	t	2026-10-05 09:56:31.551916	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
1015	16	\N	1	1	report_delivery_document	\N	stock.report_delivery_document	qweb	stock/report/report_deliveryslip.xml	primary	\N	{"en_US": "<t t-name=\\"stock.report_delivery_document\\">\\n        <t t-call=\\"web.html_container\\">\\n            <t t-set=\\"partner\\" t-value=\\"o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False\\"/>\\n            <t t-set=\\"address\\">\\n                <div name=\\"div_outgoing_address\\">\\n                    <div name=\\"outgoing_delivery_address\\" t-if=\\"o.should_print_delivery_address()\\">\\n                        <strong>Delivery Address</strong>\\n                        <div t-out=\\"o.move_ids[0].partner_id or o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                    <div name=\\"outgoing_warehouse_address\\" t-elif=\\"o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id\\">\\n                        <strong>Warehouse Address</strong>\\n                        <div t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                </div>\\n            </t>\\n            <t t-set=\\"information_block\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-7\\" name=\\"div_incoming_address\\">\\n                        <t t-set=\\"show_partner\\" t-value=\\"False\\"/>\\n                        <div name=\\"vendor_address\\" t-if=\\"o.picking_type_id.code=='incoming' and partner\\">\\n                            <strong>From</strong>\\n                            <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                        </div>\\n                        <div name=\\"customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id\\">\\n                            <strong>Customer</strong>\\n                            <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                        </div>\\n                        <div t-if=\\"show_partner\\" name=\\"partner_header\\">\\n                            <div t-field=\\"partner.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n            <t t-call=\\"web.external_layout\\" partner=\\"partner\\" address=\\"address\\" information_block=\\"information_block\\">\\n                <t t-set=\\"o\\" t-value=\\"o.with_context(lang=o._get_report_lang())\\"/>\\n                <div class=\\"page\\">\\n                    <h2 style=\\"margin-top: 15px;\\">\\n                        <span t-out=\\"o._get_deliveryslip_report_title()\\"/>\\n                        <span t-field=\\"o.name\\">WH/OUT/0001</span>\\n                    </h2>\\n                    <div class=\\"oe_structure\\"/>\\n                    <div id=\\"informations\\" class=\\"report-wrapping-flexbox clearfix row mb-4\\">\\n                        <div t-if=\\"o.origin\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_origin\\">\\n                            <strong>Order</strong>\\n                            <div t-field=\\"o.origin\\" class=\\"m-0\\">S0001</div>\\n                        </div>\\n                        <div t-if=\\"o.picking_type_id.code == 'internal' and o.partner_id\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_contact\\">\\n                            <strong>Contact</strong>\\n                            <div t-field=\\"o.partner_id\\" class=\\"m-0\\"/>\\n                        </div>\\n                        <div t-if=\\"o.state\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_sched_date\\">\\n                            <strong>Shipping Date</strong>\\n                            <div t-if=\\"o.state == 'done'\\" t-field=\\"o.date_done\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\" class=\\"m-0\\"/>\\n                            <div t-else=\\"\\" t-field=\\"o.scheduled_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\" class=\\"m-0\\"/>\\n                        </div>\\n                        <div t-if=\\"o.user_id\\" class=\\"col-auto\\" name=\\"div_operator\\">\\n                            <strong>Operator:</strong>\\n                                <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                        </div>\\n                    </div>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                    <table class=\\"table table-sm table-borderless\\" t-if=\\"o.state!='done'\\" name=\\"stock_move_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sm_product\\"><strong>Product</strong></th>\\n                                <th name=\\"th_sm_ordered\\" class=\\"text-end\\"><strong>Ordered</strong></th>\\n                                <th name=\\"th_sm_quantity\\" class=\\"text-end\\"><strong>Delivered</strong></th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                            <t t-set=\\"lines\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty)\\"/>\\n                            <tr t-foreach=\\"lines\\" t-as=\\"move\\">\\n                                <td>\\n                                    <span t-field=\\"move.product_id\\">Customizable Desk</span>\\n                                    <p t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()\\">\\n                                        <span t-out=\\"move._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                    </p>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.product_uom_qty)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.uom_id\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_qty\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Pack of 6</span>\\n                                    </t>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.uom_id\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-out=\\"move.uom_id._compute_quantity(move.quantity, move.packaging_uom_id)\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Pack of 6</span>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                    <table class=\\"table table-sm table-borderless\\" t-elif=\\"o.move_line_ids and o.state=='done'\\" name=\\"stock_move_line_table\\">\\n                        <t t-set=\\"has_multi_level_packages\\" t-value=\\"len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"o.move_line_ids.mapped('lot_id')\\" groups=\\"stock.group_lot_on_delivery_slip\\"/>\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sml_product\\">Product</th>\\n                                <th name=\\"th_sml_package\\" t-if=\\"has_multi_level_packages\\">Package</th>\\n                                <th name=\\"th_sml_qty_ordered\\" class=\\"text-end\\" t-if=\\"not has_serial_number\\">\\n                                    Ordered\\n                                </th>\\n                                <th name=\\"lot_serial\\" class=\\"text-end\\" t-else=\\"\\">\\n                                    Lot/Serial Number\\n                                </th>\\n                                <th name=\\"th_sml_quantity\\" class=\\"text-end\\">Delivered</th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\\n                                    product + description + uom combinations\\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\\n                            <!-- If has destination packages => create sections of corresponding products -->\\n                            <t t-if=\\"o.packages_count\\" name=\\"has_packages\\">\\n                                <t t-set=\\"packages\\" t-value=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id\\"/>\\n                                <t t-foreach=\\"packages\\" t-as=\\"package\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_package_section_line\\"/>\\n                                    <t t-set=\\"package_move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')\\"/>\\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"package_move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\\n                                    <t t-else=\\"\\">\\n                                        <t t-set=\\"aggregated_lines\\" t-value=\\"package_move_lines._get_aggregated_product_quantities(strict=True)\\"/>\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                                <!-- Make sure we do another section for package-less products if they exist -->\\n                                <t t-set=\\"move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)\\"/>\\n                                <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)\\"/>\\n                                <t t-if=\\"move_lines or aggregated_lines\\" name=\\"no_package_move_lines\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_no_package_section_line\\" name=\\"no_package_section\\"/>\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-elif=\\"aggregated_lines\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                            </t>\\n                            <!-- No destination packages -->\\n                            <t t-else=\\"\\">\\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                <t t-if=\\"has_serial_number\\">\\n                                    <tr t-foreach=\\"o.move_ids.move_line_ids\\" t-as=\\"move_line\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                    </tr>\\n                                </t>\\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\\n                                <t t-else=\\"\\" name=\\"aggregated_move_lines\\">\\n                                    <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities()\\"/>\\n                                    <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"backorders\\" t-value=\\"o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))\\"/>\\n                    <div t-if=\\"not (o.backorder_ids and backorders)\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\">\\n                        <p class=\\"mt-5\\">\\n                            <span>Remaining quantities not yet delivered:</span>\\n                        </p>\\n                        <table class=\\"table table-sm table-borderless\\" name=\\"stock_backorder_table\\">\\n                            <thead>\\n                                <tr>\\n                                    <th name=\\"th_sb_product\\"><strong>Product</strong></th>\\n                                    <th/>\\n                                    <th name=\\"th_sb_quantity\\" class=\\"text-end\\"><strong>Quantity</strong></th>\\n                                </tr>\\n                            </thead>\\n                            <tbody>\\n                                <tr t-foreach=\\"backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)\\" t-as=\\"bo_line\\">\\n                                    <td class=\\"w-auto\\">\\n                                        <span t-field=\\"bo_line.product_id\\">Office Chair</span>\\n                                        <p t-if=\\"bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line._get_report_description_picking()\\">\\n                                            <span t-out=\\"bo_line._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                        </p>\\n                                    </td>\\n                                    <td/>\\n                                    <td class=\\"text-end w-auto\\">\\n                                        <span t-out=\\"format_number(bo_line.product_uom_qty)\\">3.00</span>\\n                                        <span t-field=\\"bo_line.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                    </td>\\n                                </tr>\\n                            </tbody>\\n                        </table>\\n                    </div>\\n\\n                    <div t-if=\\"not o.signature\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\" class=\\"mt32 ml64 mr4\\" name=\\"signature\\">\\n                        <div class=\\"offset-8\\">\\n                            <strong>Signature</strong>\\n                        </div>\\n                        <div class=\\"offset-8\\">\\n                            <img t-att-src=\\"image_data_uri(o.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                        </div>\\n                        <div t-if=\\"o.partner_id.name\\" class=\\"offset-8 text-center\\">\\n                            <p t-field=\\"o.partner_id.name\\">John Doe</p>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n         </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_delivery_document">\n        <t t-call="web.html_container">\n            <t t-set="partner" t-value="o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False"/>\n            <t t-set="address">\n                <div name="div_outgoing_address">\n                    <div name="outgoing_delivery_address" t-if="o.should_print_delivery_address()">\n                        <strong>Delivery Address</strong>\n                        <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n                    <div name="outgoing_warehouse_address" t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                        <strong>Warehouse Address</strong>\n                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n                </div>\n            </t>\n            <t t-set="information_block">\n                <div class="row">\n                    <div class="col-7" name="div_incoming_address">\n                        <t t-set="show_partner" t-value="False"/>\n                        <div name="vendor_address" t-if="o.picking_type_id.code=='incoming' and partner">\n                            <strong>From</strong>\n                            <t t-set="show_partner" t-value="True"/>\n                        </div>\n                        <div name="customer_address" t-if="o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id">\n                            <strong>Customer</strong>\n                            <t t-set="show_partner" t-value="True"/>\n                        </div>\n                        <div t-if="show_partner" name="partner_header">\n                            <div t-field="partner.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                    </div>\n                </div>\n            </t>\n            <t t-call="web.external_layout" partner="partner" address="address" information_block="information_block">\n                <t t-set="o" t-value="o.with_context(lang=o._get_report_lang())"/>\n                <div class="page">\n                    <h2 style="margin-top: 15px;">\n                        <span t-out="o._get_deliveryslip_report_title()"/>\n                        <span t-field="o.name">WH/OUT/0001</span>\n                    </h2>\n                    <div class="oe_structure"/>\n                    <div id="informations" class="report-wrapping-flexbox clearfix row mb-4">\n                        <div t-if="o.origin" class="col col-3 mw-100 mb-2" name="div_origin">\n                            <strong>Order</strong>\n                            <div t-field="o.origin" class="m-0">S0001</div>\n                        </div>\n                        <div t-if="o.picking_type_id.code == 'internal' and o.partner_id" class="col col-3 mw-100 mb-2" name="div_contact">\n                            <strong>Contact</strong>\n                            <div t-field="o.partner_id" class="m-0"/>\n                        </div>\n                        <div t-if="o.state" class="col col-3 mw-100 mb-2" name="div_sched_date">\n                            <strong>Shipping Date</strong>\n                            <div t-if="o.state == 'done'" t-field="o.date_done" t-options="{&quot;widget&quot;: &quot;date&quot;}" class="m-0"/>\n                            <div t-else="" t-field="o.scheduled_date" t-options="{&quot;widget&quot;: &quot;date&quot;}" class="m-0"/>\n                        </div>\n                        <div t-if="o.user_id" class="col-auto" name="div_operator">\n                            <strong>Operator:</strong>\n                                <p t-field="o.user_id">Mitchel Admin</p>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                    <t t-set="format_number" t-value="lambda x: int(x) if x == int(x) else x"/>\n                    <table class="table table-sm table-borderless" t-if="o.state!='done'" name="stock_move_table">\n                        <thead>\n                            <tr>\n                                <th name="th_sm_product"><strong>Product</strong></th>\n                                <th name="th_sm_ordered" class="text-end"><strong>Ordered</strong></th>\n                                <th name="th_sm_quantity" class="text-end"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-set="lines" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty)"/>\n                            <tr t-foreach="lines" t-as="move">\n                                <td>\n                                    <span t-field="move.product_id">Customizable Desk</span>\n                                    <p t-if="move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()">\n                                        <span t-out="move._get_report_description_picking()" t-options="{'widget': 'text'}">Description on transfer</span>\n                                    </p>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.product_uom_qty)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.uom_id" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.uom_id" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-field="move.packaging_uom_qty">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.quantity)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.uom_id" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.uom_id" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-out="move.uom_id._compute_quantity(move.quantity, move.packaging_uom_id)">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <table class="table table-sm table-borderless" t-elif="o.move_line_ids and o.state=='done'" name="stock_move_line_table">\n                        <t t-set="has_multi_level_packages" t-value="len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0"/>\n                        <t t-set="has_serial_number" t-value="False"/>\n                        <t t-set="has_serial_number" t-value="o.move_line_ids.mapped('lot_id')" groups="stock.group_lot_on_delivery_slip"/>\n                        <thead>\n                            <tr>\n                                <th name="th_sml_product">Product</th>\n                                <th name="th_sml_package" t-if="has_multi_level_packages">Package</th>\n                                <th name="th_sml_qty_ordered" class="text-end" t-if="not has_serial_number">\n                                    Ordered\n                                </th>\n                                <th name="lot_serial" class="text-end" t-else="">\n                                    Lot/Serial Number\n                                </th>\n                                <th name="th_sml_quantity" class="text-end">Delivered</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\n                                    product + description + uom combinations\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\n                            <!-- If has destination packages => create sections of corresponding products -->\n                            <t t-if="o.packages_count" name="has_packages">\n                                <t t-set="packages" t-value="o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id"/>\n                                <t t-foreach="packages" t-as="package">\n                                    <t t-call="stock.stock_report_delivery_package_section_line"/>\n                                    <t t-set="package_move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')"/>\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="package_move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\n                                    <t t-else="">\n                                        <t t-set="aggregated_lines" t-value="package_move_lines._get_aggregated_product_quantities(strict=True)"/>\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                                <!-- Make sure we do another section for package-less products if they exist -->\n                                <t t-set="move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)"/>\n                                <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)"/>\n                                <t t-if="move_lines or aggregated_lines" name="no_package_move_lines">\n                                    <t t-call="stock.stock_report_delivery_no_package_section_line" name="no_package_section"/>\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <t t-elif="aggregated_lines">\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                            </t>\n                            <!-- No destination packages -->\n                            <t t-else="">\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\n                                <t t-if="has_serial_number">\n                                    <tr t-foreach="o.move_ids.move_line_ids" t-as="move_line">\n                                        <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                    </tr>\n                                </t>\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\n                                <t t-else="" name="aggregated_move_lines">\n                                    <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities()"/>\n                                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                    <div class="oe_structure"/>\n                    <t t-set="backorders" t-value="o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))"/>\n                    <div t-if="not (o.backorder_ids and backorders)" class="oe_structure"/>\n                    <div t-else="">\n                        <p class="mt-5">\n                            <span>Remaining quantities not yet delivered:</span>\n                        </p>\n                        <table class="table table-sm table-borderless" name="stock_backorder_table">\n                            <thead>\n                                <tr>\n                                    <th name="th_sb_product"><strong>Product</strong></th>\n                                    <th/>\n                                    <th name="th_sb_quantity" class="text-end"><strong>Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr t-foreach="backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)" t-as="bo_line">\n                                    <td class="w-auto">\n                                        <span t-field="bo_line.product_id">Office Chair</span>\n                                        <p t-if="bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line._get_report_description_picking()">\n                                            <span t-out="bo_line._get_report_description_picking()" t-options="{'widget': 'text'}">Description on transfer</span>\n                                        </p>\n                                    </td>\n                                    <td/>\n                                    <td class="text-end w-auto">\n                                        <span t-out="format_number(bo_line.product_uom_qty)">3.00</span>\n                                        <span t-field="bo_line.uom_id" groups="uom.group_uom">units</span>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n\n                    <div t-if="not o.signature" class="oe_structure"/>\n                    <div t-else="" class="mt32 ml64 mr4" name="signature">\n                        <div class="offset-8">\n                            <strong>Signature</strong>\n                        </div>\n                        <div class="offset-8">\n                            <img t-att-src="image_data_uri(o.signature)" style="max-height: 4cm; max-width: 8cm;"/>\n                        </div>\n                        <div t-if="o.partner_id.name" class="offset-8 text-center">\n                            <p t-field="o.partner_id.name">John Doe</p>\n                        </div>\n                    </div>\n                </div>\n            </t>\n         </t>\n    </t>\n\n    	\N	f	t	2026-10-05 09:56:31.551916	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
1016	16	\N	1	1	stock_report_delivery_has_serial_move_line	\N	stock.stock_report_delivery_has_serial_move_line	qweb	stock/report/report_deliveryslip.xml	primary	\N	{"en_US": "<t t-name=\\"stock.stock_report_delivery_has_serial_move_line\\">\\n        <td>\\n            <span t-field=\\"move_line.product_id\\"/>\\n            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->\\n            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard \\"if\\" condition -->\\n            <!-- let's agree that pre-filtered descriptions will be set to \\"\\" -->\\n            <t t-if=\\"not description and description != ''\\">\\n                <t t-set=\\"description\\" t-value=\\"move_line.move_id.description_picking\\"/>\\n            </t>\\n            <p t-if=\\"description != '' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name\\">\\n                <span t-out=\\"description\\" t-options=\\"{'widget': 'text'}\\"/>\\n            </p>\\n        </td>\\n        <td t-if=\\"has_multi_level_packages\\">\\n            <t t-if=\\"move_line.result_package_id != package\\">\\n                <span t-if=\\"move_line.package_history_id\\" t-out=\\"move_line.package_history_id._get_complete_dest_name_except_outermost()\\"/>\\n                <span t-else=\\"\\" t-field=\\"move_line.result_package_id\\"/>\\n            </t>\\n        </td>\\n        <t t-if=\\"has_serial_number\\" name=\\"move_line_lot\\">\\n            <td class=\\"text-end\\"><span t-field=\\"move_line.lot_id.name\\"/></td>\\n        </t>\\n        <td class=\\"text-end\\" name=\\"move_line_lot_quantity\\">\\n            <span t-out=\\"format_number(move_line.quantity)\\"/>\\n            <span t-field=\\"move_line.uom_id\\"/>\\n            <t t-if=\\"move_line.move_id.packaging_uom_id != move_line.uom_id\\" groups=\\"uom.group_uom\\">\\n                <br/>\\n                <span class=\\"text-muted\\" t-out=\\"move_line.uom_id._compute_quantity(move_line.quantity, move_line.move_id.packaging_uom_id)\\">1.00</span>\\n                <span class=\\"text-muted\\" t-field=\\"move_line.move_id.packaging_uom_id\\">Pack of 6</span>\\n            </t>\\n        </td>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.stock_report_delivery_has_serial_move_line">\n        <td>\n            <span t-field="move_line.product_id"/>\n            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->\n            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard "if" condition -->\n            <!-- let's agree that pre-filtered descriptions will be set to "" -->\n            <t t-if="not description and description != ''">\n                <t t-set="description" t-value="move_line.move_id.description_picking"/>\n            </t>\n            <p t-if="description != '' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name">\n                <span t-out="description" t-options="{'widget': 'text'}"/>\n            </p>\n        </td>\n        <td t-if="has_multi_level_packages">\n            <t t-if="move_line.result_package_id != package">\n                <span t-if="move_line.package_history_id" t-out="move_line.package_history_id._get_complete_dest_name_except_outermost()"/>\n                <span t-else="" t-field="move_line.result_package_id"/>\n            </t>\n        </td>\n        <t t-if="has_serial_number" name="move_line_lot">\n            <td class="text-end"><span t-field="move_line.lot_id.name"/></td>\n        </t>\n        <td class="text-end" name="move_line_lot_quantity">\n            <span t-out="format_number(move_line.quantity)"/>\n            <span t-field="move_line.uom_id"/>\n            <t t-if="move_line.move_id.packaging_uom_id != move_line.uom_id" groups="uom.group_uom">\n                <br/>\n                <span class="text-muted" t-out="move_line.uom_id._compute_quantity(move_line.quantity, move_line.move_id.packaging_uom_id)">1.00</span>\n                <span class="text-muted" t-field="move_line.move_id.packaging_uom_id">Pack of 6</span>\n            </t>\n        </td>\n    </t>\n    	\N	f	t	2026-10-05 09:56:31.551916	2026-10-05 09:56:37.547541	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	\N
