ame=\\"User\\" context=\\"{'group_by':'user_id'}\\"/>\\n                    <filter string=\\"Sales Team\\" name=\\"sales_channel\\" context=\\"{'group_by':'team_id'}\\"/>\\n                    <filter string=\\"Customer\\" name=\\"Customer\\" context=\\"{'group_by':'partner_id'}\\"/>\\n                    <filter string=\\"Customer Country\\" name=\\"country_id\\" context=\\"{'group_by':'country_id'}\\"/>\\n                    <filter string=\\"Customer Industry\\" name=\\"industry_id\\" context=\\"{'group_by':'industry_id'}\\"/>\\n                    <filter string=\\"Customer Tags\\" name=\\"partner_tag_ids\\" context=\\"{'group_by': 'partner_tag_ids'}\\"/>\\n                    <filter string=\\"Product\\" name=\\"product_tmpl_id\\" context=\\"{'group_by':'product_tmpl_id'}\\"/>\\n                    <filter string=\\"Product Variant\\" name=\\"product_id\\" context=\\"{'group_by':'product_id'}\\" groups=\\"product.group_product_variant\\"/>\\n                    <filter string=\\"Product Category\\" name=\\"Category\\" context=\\"{'group_by':'categ_id'}\\"/>\\n                    <filter string=\\"Status\\" name=\\"status\\" context=\\"{'group_by':'state'}\\"/>\\n                    <filter string=\\"Company\\" name=\\"company\\" groups=\\"base.group_multi_company\\" context=\\"{'group_by':'company_id'}\\"/>\\n                    <separator/>\\n                    <filter string=\\"Order Date\\" name=\\"group_by_date\\" context=\\"{'group_by':'date'}\\" invisible=\\"context.get('sale_report_view_hide_date')\\"/>\\n                    <filter string=\\"Order Date\\" name=\\"group_by_date_day\\" context=\\"{'group_by':'date:day'}\\" invisible=\\"not context.get('sale_report_view_hide_date')\\"/>\\n                </group>\\n            </search>"}	<?xml version="1.0"?>\n<search string="Sales Analysis">\n                <field name="date"/>\n                <filter string="Date" name="year" invisible="1" date="date" default_period="year"/>\n                <filter string="Quotations" name="Quotations" domain="[('state','in', ('draft', 'sent'))]"/>\n                <filter string="Sales Orders" name="Sales" domain="[('state','not in',('draft', 'cancel', 'sent'))]"/>\n                <filter string="Not Cancelled" name="filter_not_cancelled" domain="[('state', '!=', 'cancel')]"/>\n                <separator/>\n                <filter name="filter_date" date="date" default_period="month"/>\n                <filter name="filter_order_date" invisible="1" string="Order Date: Last 365 Days" domain="[('date', '&gt;=', '-365d')]"/>\n                <separator/>\n                <field name="user_id"/>\n                <field name="team_id"/>\n                <field name="product_id"/>\n                <field name="product_tmpl_id"/>\n                <field name="categ_id"/>\n                <filter name="to_invoice" string="To Invoice" domain="[('line_invoice_status', '=', 'to invoice')]"/>\n                <filter name="fully_invoiced" string="Fully Invoiced" domain="[('line_invoice_status', '=', 'invoiced')]"/>\n                <field name="partner_id"/>\n                <field name="country_id"/>\n                <field name="industry_id"/>\n                <group>\n                    <field name="categ_id" filter_domain="[('categ_id', 'child_of', self)]"/>\n                    <field name="company_id" groups="base.group_multi_company"/>\n                </group>\n                <group>\n                    <filter string="Salesperson" name="User" context="{'group_by':'user_id'}"/>\n                    <filter string="Sales Team" name="sales_channel" context="{'group_by':'team_id'}"/>\n                    <filter string="Customer" name="Customer" context="{'group_by':'partner_id'}"/>\n                    <filter string="Customer Country" name="country_id" context="{'group_by':'country_id'}"/>\n                    <filter string="Customer Industry" name="industry_id" context="{'group_by':'industry_id'}"/>\n                    <filter string="Customer Tags" name="partner_tag_ids" context="{'group_by': 'partner_tag_ids'}"/>\n                    <filter string="Product" name="product_tmpl_id" context="{'group_by':'product_tmpl_id'}"/>\n                    <filter string="Product Variant" name="product_id" context="{'group_by':'product_id'}" groups="product.group_product_variant"/>\n                    <filter string="Product Category" name="Category" context="{'group_by':'categ_id'}"/>\n                    <filter string="Status" name="status" context="{'group_by':'state'}"/>\n                    <filter string="Company" name="company" groups="base.group_multi_company" context="{'group_by':'company_id'}"/>\n                    <separator/>\n                    <filter string="Order Date" name="group_by_date" context="{'group_by':'date'}" invisible="context.get('sale_report_view_hide_date')"/>\n                    <filter string="Order Date" name="group_by_date_day" context="{'group_by':'date:day'}" invisible="not context.get('sale_report_view_hide_date')"/>\n                </group>\n            </search>\n        	\N	f	t	2026-10-05 09:56:51.974485	2026-10-05 09:56:51.974485	f	\N	\N	\N	public	\N	\N	\N	\N	\N	f	f
