2006	16	\N	1	1	sale.order.form	sale.order	\N	form	sale/views/sale_order_views.xml	primary	\N	{"en_US": "<form string=\\"Sales Order\\" class=\\"o_sale_order\\" js_class=\\"sale_order_form\\">\\n            <header>\\n                <button string=\\"Capture Transaction\\" name=\\"payment_action_capture\\" type=\\"object\\" data-hotkey=\\"shift+g\\" class=\\"oe_highlight\\" invisible=\\"not has_authorized_transaction_ids\\"/>\\n                <button string=\\"Void Transaction\\" name=\\"payment_action_void\\" type=\\"object\\" data-hotkey=\\"shift+v\\" confirm=\\"Are you sure you want to void the authorized transaction? This action can't be undone.\\" invisible=\\"not has_authorized_transaction_ids\\"/>\\n                <button string=\\"Create Invoice\\" id=\\"create_invoice\\" name=\\"497\\" type=\\"action\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'to invoice' and not (has_overages and invoice_status == 'upselling')\\"/>\\n                <button string=\\"Create Invoice\\" id=\\"create_invoice_percentage\\" name=\\"497\\" type=\\"action\\" context=\\"{'default_advance_payment_method': 'percentage'}\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'no' or state != 'sale'\\"/>\\n                <button string=\\"Send\\" id=\\"quotation_send_primary\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'validate_analytic': True, 'check_document_layout': True}\\" class=\\"btn-primary\\" data-hotkey=\\"g\\" invisible=\\"state != 'draft'\\"/>\\n                <button string=\\"Send PRO FORMA Invoice\\" id=\\"send_proforma_primary\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'proforma': True, 'validate_analytic': True}\\" class=\\"btn-primary\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state != 'draft' or invoice_count &gt;= 1\\"/>\\n                <button string=\\"Confirm\\" id=\\"action_confirm\\" name=\\"action_confirm\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"state != 'sent'\\"/>\\n                <button string=\\"Download\\" name=\\"sale.action_report_saleorder\\" type=\\"action\\" data-hotkey=\\"i\\" invisible=\\"state == 'sale'\\"/>\\n                <button string=\\"Confirm\\" name=\\"action_confirm\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" data-hotkey=\\"q\\" invisible=\\"state != 'draft'\\"/>\\n                <button string=\\"Send PRO FORMA Invoice\\" id=\\"send_proforma\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'proforma': True, 'validate_analytic': True}\\" invisible=\\"state == 'draft' or invoice_count &gt;= 1\\" groups=\\"sale.group_proforma_sales\\"/>\\n                <button string=\\"Send\\" id=\\"quotation_send\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'validate_analytic': True, 'check_document_layout': True}\\" data-hotkey=\\"g\\" invisible=\\"state not in ('sent', 'sale')\\"/>\\n\\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\\n                <button string=\\"Unlock\\" name=\\"action_unlock\\" type=\\"object\\" invisible=\\"not locked\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                <button string=\\"Preview\\" name=\\"action_preview_sale_order\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                <button string=\\"Cancel\\" name=\\"action_cancel\\" type=\\"object\\" confirm-title=\\"Cancel Order\\" confirm=\\"Cancelling this order will set its status to 'Cancelled' and will update related documents and processes. Are you sure?\\" confirm-label=\\"Yes, cancel order\\" cancel-label=\\"No, go back\\" data-hotkey=\\"x\\" invisible=\\"state not in ['draft', 'sent', 'sale'] or not id or locked\\"/>\\n                <button string=\\"Set to Quotation\\" name=\\"action_draft\\" type=\\"object\\" data-hotkey=\\"w\\" invisible=\\"state != 'cancel'\\"/>\\n                <t groups=\\"sale.group_auto_done_setting\\">\\n                    <button string=\\"Lock\\" name=\\"action_lock\\" type=\\"object\\" help=\\"If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver.\\" invisible=\\"locked or state != 'sale'\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                </t>\\n                <button string=\\"Reopen Invoicing\\" name=\\"action_reopen_order\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"not invoicing_closed or state != 'sale'\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sent,sale\\"/>\\n            </header>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not sale_warning_text\\">\\n                <field name=\\"sale_warning_text\\" class=\\"fw-bold\\"/>\\n            </div>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"partner_credit_warning == ''\\">\\n                <field name=\\"partner_credit_warning\\"/>\\n            </div>\\n            <div class=\\"alert alert-warning p-3 text-center\\" role=\\"alert\\" invisible=\\"state not in ['draft', 'sent'] or not has_archived_products\\">\\n                <span>Warning: This quote contains archived product(s)</span>\\n            </div>\\n            <div class=\\"alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"state != 'draft' or not duplicated_order_ids\\" role=\\"alert\\">\\n                <span>Warning: this order might be a duplicate of</span>\\n                <field name=\\"duplicated_order_ids\\" widget=\\"x2many_buttons\\" string=\\"Duplicated Documents\\"/>\\n            </div>\\n            <sheet>\\n                <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                    <button name=\\"action_view_invoice\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" invisible=\\"invoice_count == 0\\">\\n                        <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Invoices\\"/>\\n                    </button>\\n                    <button name=\\"action_view_payment_transaction\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"payments\\" groups=\\"account.group_account_invoice,base.group_no_one\\">\\n                        <field name=\\"transaction_count\\" widget=\\"statinfo\\" string=\\"Payments\\"/>\\n                    </button>\\n                </div>\\n                <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                    <i class=\\"oi\\" data-icon=\\"lock\\"/>\\n                    Locked\\n                </div>\\n                <div class=\\"oe_title\\">\\n                    <h1 class=\\"o_outlined\\">\\n                        <field name=\\"name\\" readonly=\\"1\\"/>\\n                    </h1>\\n                </div>\\n                <group name=\\"sale_header\\">\\n                    <group name=\\"partner_details\\">\\n                        <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}\\" placeholder=\\"Type to find a customer...\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <field name=\\"partner_invoice_id\\" groups=\\"account.group_delivery_invoice_address\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_type': 'invoice', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                        <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_type': 'delivery', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                    </group>\\n                    <group name=\\"order_details\\">\\n                        <field name=\\"validity_date\\" invisible=\\"state == 'sale'\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\">\\n                            <label for=\\"date_order\\" string=\\"Quotation Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" invisible=\\"state in ['draft', 'sent']\\">\\n                            <label for=\\"date_order\\" string=\\"Order Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" invisible=\\"state in ['draft', 'sent']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <label for=\\"pricelist_id\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not has_active_pricelist\\"/>\\n                        <div groups=\\"product.group_product_pricelist\\" class=\\"o_row\\" invisible=\\"not has_active_pricelist\\">\\n                            <field name=\\"pricelist_id\\" options=\\"{'no_open': True, 'no_create': True}\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        </div>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"pricelist_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'sale']\\" groups=\\"!product.group_product_pricelist\\"/>\\n                        <field name=\\"payment_term_id\\" placeholder=\\"Immediate\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                        <label for=\\"commitment_date\\" invisible=\\"state == 'draft'\\"/>\\n                        <label for=\\"commitment_date\\" string=\\"Delivery Date\\" invisible=\\"state != 'draft'\\"/>\\n                        <div name=\\"commitment_date_div\\" class=\\"o_row align-items-center\\">\\n                            <field name=\\"commitment_date\\" options=\\"{'placeholder_field': 'expected_date'}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                            <field name=\\"delivery_status\\" widget=\\"badge\\" decoration-success=\\"delivery_status == 'full'\\" decoration-warning=\\"delivery_status == 'partial'\\" decoration-info=\\"delivery_status in ['pending', 'started']\\" invisible=\\"state != 'sale'\\"/>\\n                        </div>\\n                        <field name=\\"expected_date\\" invisible=\\"1\\"/>  <!-- Needed for the placeholder widget -->\\n                   </group>\\n                   <div>\\n                        <field name=\\"document_tax_mode\\" id=\\"document_tax_mode_mobile\\" class=\\"tax_mode_badge d-md-none\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\"/>\\n                    </div>\\n                </group>\\n                <notebook>\\n                    <page string=\\"Order Lines\\" name=\\"order_lines\\">\\n                    <div class=\\"position-relative document_tax_mode\\">\\n                        <field name=\\"document_tax_mode\\" id=\\"document_tax_mode\\" class=\\"overlap_badge_tab tax_mode_badge d-none d-md-block\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\"/>\\n                    </div>\\n                        <field name=\\"order_line\\" widget=\\"sol_o2m\\" mode=\\"list,kanban\\" class=\\"o_sale_order_line_o2m\\" readonly=\\"state == 'cancel' or locked\\" aggregated_fields=\\"price_subtotal,price_total\\" options=\\"{'hide_composition': True, 'hide_prices': True, 'subsections': True}\\">\\n                            <form>\\n                                <field name=\\"technical_price_unit\\" invisible=\\"1\\"/>\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <!-- Display_type must be specified as non readonly (which would be the case with the default field added by ORM) -->\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"product_id\\"/>\\n                                        <div class=\\"d-flex align-items-baseline\\">\\n                                            <span class=\\"oi text-warning me-1\\" data-icon=\\"warning\\" title=\\"This product is archived\\" invisible=\\"state not in ['draft', 'sent'] or not is_product_archived\\"/>\\n                                            <field name=\\"product_id\\" context=\\"{                                                     'default_uom_id': product_uom_id,                                                     'partner_id': parent.partner_id,                                                 }\\" readonly=\\"not product_updatable\\" required=\\"mandatory_product and not display_type and not is_downpayment\\" force_save=\\"1\\" widget=\\"many2one_barcode\\"/>\\n                                        </div>\\n                                        <field name=\\"name\\"/>\\n                                        <label for=\\"product_uom_qty\\"/>\\n                                        <div class=\\"o_row\\" name=\\"ordered_qty\\">\\n                                            <field name=\\"product_uom_qty\\"/>\\n                                            <field name=\\"product_uom_id\\" force_save=\\"1\\" groups=\\"uom.group_uom\\" class=\\"oe_no_button\\" widget=\\"many2one_uom\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type and not is_downpayment\\"/>\\n                                            <widget name=\\"simple_qty_at_date_widget\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_delivered\\" string=\\"Delivered\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"delivered_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_delivered\\" readonly=\\"qty_delivered_method != 'manual'\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_invoiced\\" string=\\"Invoiced\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"invoiced_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_invoiced\\"/>\\n                                        </div>\\n                                        <field name=\\"price_unit\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" context=\\"{'search_view_ref': 'account.account_tax_view_search'}\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                        <t groups=\\"sale.group_discount_per_so_line\\">\\n                                            <label for=\\"discount\\"/>\\n                                            <div name=\\"discount\\">\\n                                                <field name=\\"discount\\" class=\\"oe_inline\\"/> %\\n                                            </div>\\n                                        </t>\\n                                    </group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"customer_lead\\"/>\\n                                        <div name=\\"lead\\">\\n                                            <field name=\\"customer_lead\\" class=\\"oe_inline\\" readonly=\\"product_type != 'consu'\\"/> days\\n                                        </div>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order'}\\"/>\\n                                    </group>\\n                                </group>\\n                                <label for=\\"name\\" string=\\"Section Name (eg. Products, Services)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                <label for=\\"name\\" string=\\"Subsection Name\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                <field name=\\"name\\" invisible=\\"not display_type\\"/>\\n                                <group>\\n                                    <field name=\\"collapse_composition\\" string=\\"Hide Composition\\" invisible=\\"display_type not in ['line_section', 'line_subsection']\\" readonly=\\"1\\"/>\\n                                    <field name=\\"collapse_prices\\" string=\\"Hide Prices\\" invisible=\\"display_type not in ['line_section', 'line_subsection']\\" readonly=\\"1\\"/>\\n                                </group>\\n                                <field name=\\"invoice_lines\\" invisible=\\"1\\"/>\\n                            </form>\\n                            <list name=\\"sol_list\\" string=\\"Sales Order Lines\\" editable=\\"bottom\\" limit=\\"200\\" decoration-warning=\\"(state in ['draft', 'sent'] and is_product_archived) or sale_line_warn_msg\\">\\n                                <control>\\n                                    <create string=\\"Add Line\\" name=\\"add_product_control\\" data-hotkey=\\"shift+p\\"/>\\n                                    <create string=\\"Add Section\\" name=\\"add_section_control\\" data-hotkey=\\"shift+h\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create string=\\"Add Note\\" name=\\"add_note_control\\" data-hotkey=\\"shift+n\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button string=\\"Catalog\\" data-hotkey=\\"shift+k\\" name=\\"action_add_from_catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n\\n                                <!-- Non readonly invisible fields, must be specified manually, because fields added automatically by the ORM\\n                                    are readonly, widgets fieldDependencies too -->\\n                                <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_custom_attribute_value_ids\\" column_invisible=\\"1\\">\\n                                    <list>\\n                                        <field name=\\"custom_product_template_attribute_value_id\\"/>\\n                                        <field name=\\"custom_value\\"/>\\n                                    </list>\\n                                </field>\\n                                <field name=\\"product_no_variant_attribute_value_ids\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"technical_price_unit\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_line_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"combo_item_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"selected_combo_items\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_composition\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_prices\\" column_invisible=\\"1\\"/>\\n\\n                                <!-- Currency, needed for monetary widgets to display the currency symbol -->\\n                                <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n\\n                                <!-- Standard fields -->\\n                                <field name=\\"sequence\\" invisible=\\"combo_item_id\\" widget=\\"handle\\"/>\\n                                <widget name=\\"line_number\\" nolabel=\\"1\\" column_invisible=\\"not parent.show_sol_numbers\\" width=\\"29px\\"/>\\n                                <column name=\\"product_and_description\\" string=\\"Description\\">\\n                                    <field name=\\"product_template_id\\" string=\\"Product\\" readonly=\\"id and not product_updatable\\" required=\\"mandatory_product and not display_type and not is_downpayment\\" context=\\"{                                             'default_list_price': price_unit,                                             'default_uom_id': product_uom_id,                                             'partner_id': parent.partner_id,                                         }\\" optional=\\"hide\\" widget=\\"sol_product_many2one\\" placeholder=\\"Type to find a product...\\" invisible=\\"display_type\\"/>\\n                                    <field name=\\"product_id\\" string=\\"Product Variant\\" readonly=\\"not product_updatable\\" required=\\"mandatory_product and not display_type and not is_downpayment\\" force_save=\\"1\\" context=\\"{                                             'default_lst_price': price_unit,                                             'default_uom_id': product_uom_id,                                             'partner_id': parent.partner_id,                                         }\\" optional=\\"hide\\" widget=\\"sol_product_many2one\\" placeholder=\\"Type to find a product...\\" invisible=\\"display_type\\"/>\\n                                    <field name=\\"name\\" placeholder=\\"Enter a description...\\" decoration-it=\\"not display_type\\" required=\\"display_type\\" widget=\\"text\\"/>\\n                                    <field name=\\"label\\" widget=\\"sol_label_text\\" context=\\"{'partner_id': parent.partner_id}\\" invisible=\\"display_type\\" required=\\"1\\"/>\\n                                </column>\\n                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" options=\\"{                                         'product_field': 'product_id',                                         'business_domain': 'sale_order',                                         'amount_field': 'price_subtotal',                                     }\\" optional=\\"hide\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                <column name=\\"sol_qty\\">\\n                                    <field name=\\"product_uom_qty\\" invisible=\\"display_type\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"section_qty\\" invisible=\\"display_type not in ('line_section', 'line_subsection')\\" class=\\"fw-normal text-muted\\"/>\\n                                </column>\\n                                <widget name=\\"simple_qty_at_date_widget\\" width=\\"20px\\"/>\\n                                <column name=\\"sol_uom\\" width=\\"60px\\" groups=\\"uom.group_uom\\">\\n                                    <field name=\\"product_uom_id\\" invisible=\\"display_type\\" force_save=\\"1\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type and not is_downpayment\\" widget=\\"many2one_uom\\" optional=\\"show\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                                    <field name=\\"section_uom_id\\" invisible=\\"display_type not in ('line_section', 'line_subsection')\\" options=\\"{'no_open': True, 'no_create': True}\\" class=\\"fw-normal text-muted\\"/>\\n                                </column>\\n                                <column column_invisible=\\"parent.state != 'sale'\\">\\n                                    <field name=\\"qty_delivered\\" string=\\"Delivered\\" invisible=\\"display_type\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-danger=\\"qty_overage and qty_delivered &gt; qty_invoiced\\" readonly=\\"qty_delivered_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                    <field name=\\"qty_delivered_percent\\" widget=\\"labeled_percentage_field\\" invisible=\\"display_type\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" readonly=\\"qty_delivered_method != 'manual' or is_downpayment or product_uom_qty == 0\\" optional=\\"hide\\"/>\\n                                </column>\\n                                <field name=\\"qty_invoiced\\" string=\\"Invoiced\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" column_invisible=\\"parent.state != 'sale'\\" optional=\\"show\\"/>\\n                                <field name=\\"customer_lead\\" optional=\\"hide\\" width=\\"80px\\" readonly=\\"parent.state not in ['draft', 'sent', 'sale'] or is_downpayment or product_type != 'consu'\\"/>\\n                                <!--\\n                                    price_unit is wrapped in a column so inheriting modules (e.g.\\n                                    sale_margin) can add fields to it via position=\\"inside\\" instead\\n                                    of replacing the price_unit field node. A replace would silently\\n                                    discard changes made by lower-priority inherited views and\\n                                    require duplicating this definition.\\n                                -->\\n                                <column name=\\"price_unit\\">\\n                                    <field name=\\"price_unit\\" invisible=\\"display_type\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                </column>\\n                                <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" context=\\"{'active_test': True}\\" readonly=\\"qty_invoiced &gt; 0 or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"discount\\" string=\\"Disc.%\\" groups=\\"sale.group_discount_per_so_line\\" width=\\"50px\\" optional=\\"show\\"/>\\n                                <column column_invisible=\\"parent.document_tax_mode == 'tax_included'\\">\\n                                    <field name=\\"price_subtotal\\" string=\\"Amount\\" invisible=\\"is_downpayment\\"/>\\n                                    <field name=\\"price_subtotal\\" string=\\"Tax Excl.\\" invisible=\\"display_type or is_downpayment\\" widget=\\"labeled_monetary_field\\" optional=\\"hide\\"/>\\n                                    <field name=\\"price_total\\" string=\\"Tax Incl.\\" invisible=\\"display_type or is_downpayment\\" widget=\\"labeled_monetary_field\\" optional=\\"hide\\"/>\\n                                </column>\\n                                <column column_invisible=\\"parent.document_tax_mode == 'tax_excluded'\\">\\n                                    <field name=\\"price_total\\" string=\\"Amount\\" invisible=\\"is_downpayment\\"/>\\n                                    <field name=\\"price_subtotal\\" string=\\"Tax Excl.\\" invisible=\\"display_type or is_downpayment\\" widget=\\"labeled_monetary_field\\" optional=\\"hide\\"/>\\n                                    <field name=\\"price_total\\" string=\\"Tax Incl.\\" invisible=\\"display_type or is_downpayment\\" widget=\\"labeled_monetary_field\\" optional=\\"hide\\"/>\\n                                </column>\\n                                <widget name=\\"section_state\\"/>\\n                            </list>\\n                            <kanban class=\\"o_kanban_mobile\\">\\n                                <field name=\\"product_custom_attribute_value_ids\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"product_template_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"combo_item_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_line_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"selected_combo_items\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_composition\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_prices\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"product_no_variant_attribute_value_ids\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"technical_price_unit\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"display_type\\"/>\\n                                <field name=\\"currency_id\\"/>\\n                                <field name=\\"sequence\\" invisible=\\"combo_item_id\\" widget=\\"handle\\"/>\\n                                <control>\\n                                    <create string=\\"Line\\" name=\\"add_product_control\\"/>\\n                                    <create string=\\"Section\\" name=\\"add_section_control\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create string=\\"Note\\" name=\\"add_note_control\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button string=\\"Catalog\\" name=\\"action_add_from_catalog\\" type=\\"object\\" class=\\"btn-secondary\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n                                <templates>\\n                                    <t t-name=\\"card\\" class=\\"row g-0 ps-0 pe-0\\">\\n                                        <t t-if=\\"!record.display_type.raw_value\\">\\n                                            <aside t-if=\\"record.product_id.value\\" class=\\"col-auto p-1 pe-2 d-flex align-items-start\\">\\n                                                <span t-att-title=\\"record.product_id.value\\" class=\\"d-inline-block flex-shrink-0\\">\\n                                                    <field name=\\"product_id\\" widget=\\"image\\" options=\\"{'size': [38, 38], 'preview_image': 'image_128', 'img_class': 'object-fit-contain rounded'}\\"/>\\n                                                </span>\\n                                            </aside>\\n                                            <main class=\\"col\\">\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col\\">\\n                                                        <span class=\\"oi text-warning me-1\\" data-icon=\\"warning\\" title=\\"This product is archived\\" invisible=\\"state not in ['draft', 'sent'] or not is_product_archived\\"/>\\n                                                        <field t-if=\\"record.product_id.value\\" name=\\"product_id\\" class=\\"fw-bold\\"/>\\n                                                        <field t-else=\\"\\" name=\\"name\\" class=\\"fw-bold\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-auto\\">\\n                                                        <field name=\\"price_subtotal\\" class=\\"fw-bolder float-end pe-1\\" widget=\\"monetary\\"/>\\n                                                    </div>\\n                                                </div>\\n                                                <div class=\\"text-muted\\">\\n                                                    Quantity:\\n                                                    <field name=\\"product_uom_qty\\"/> <field name=\\"product_uom_id\\"/>\\n                                                </div>\\n                                                <t t-if=\\"record.discount?.raw_value\\">\\n                                                    <div class=\\"text-muted\\">\\n                                                        Discount:\\n                                                        <field name=\\"discount\\"/>%\\n                                                    </div>\\n                                                </t>\\n                                            </main>\\n                                        </t>\\n                                        <t t-if=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                            <div t-att-class=\\"{                                                 'fw-bolder': record.display_type.raw_value === 'line_section',                                                 'fw-bold': record.display_type.raw_value === 'line_subsection',                                                 'fst-italic': record.display_type.raw_value === 'line_note',                                             }\\">\\n                                                <field name=\\"name\\"/>\\n                                            </div>\\n                                        </t>\\n                                    </t>\\n                                </templates>\\n                            </kanban>\\n                        </field>\\n                        <div class=\\"d-flex flex-fill d-print-none gap-1 mb-2\\" name=\\"so_button_below_order_lines\\">\\n                            <button string=\\"Discount\\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary d-none d-md-block\\" groups=\\"sale.group_discount_per_so_line\\" invisible=\\"locked or state == 'cancel'\\"/>\\n                            <button string=\\"Discounts\\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary d-none d-md-block\\" groups=\\"sale.group_discount_per_so_line\\" disabled=\\"1\\" invisible=\\"not (locked or state == 'cancel')\\"/>\\n                            <widget name=\\"combo_menu\\" class=\\"mb-0 flex-grow-1 d-md-none\\"/>\\n                            <widget name=\\"discount_menu\\" groups=\\"sale.group_discount_per_so_line\\" invisible=\\"locked or state == 'cancel'\\" class=\\"mb-0 flex-grow-1 d-md-none\\"/>\\n                        </div>\\n                        <group name=\\"note_group\\" col=\\"6\\" class=\\"mt-2 mt-md-0\\">\\n                            <group colspan=\\"4\\" class=\\"order-1 order-lg-0\\">\\n                                <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Terms and conditions...\\"/>\\n                            </group>\\n                            <group class=\\"oe_subtotal_footer border-top-0 d-flex order-0 order-lg-1 flex-column gap-3\\" colspan=\\"2\\" name=\\"sale_total\\">\\n                                <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" readonly=\\"1\\"/>\\n                                <field name=\\"extra_total_fields\\" widget=\\"sale-extra-totals\\" nolabel=\\"1\\" readonly=\\"1\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                    <page string=\\"Other Info\\" name=\\"other_information\\">\\n                        <group>\\n                            <group name=\\"confirmation_info\\" string=\\"Confirmation\\">\\n                                <field name=\\"require_signature\\" widget=\\"boolean_toggle\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                <label for=\\"prepayment_percent\\" class=\\"text-nowrap\\"/>\\n                                <span class=\\"d-inline-flex align-items-baseline\\">\\n                                    <field name=\\"prepayment_percent\\" readonly=\\"state in ['cancel', 'sale']\\" widget=\\"percentage\\" class=\\"oe_inline\\"/>\\n                                    <field name=\\"prepayment_amount\\" readonly=\\"state in ['cancel', 'sale']\\" widget=\\"monetary\\" class=\\"ms-3 oe_inline text-muted\\"/>\\n                                </span>\\n                            </group>\\n                            <group name=\\"sales_person\\" string=\\"Sales\\">\\n                                <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                <field name=\\"team_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"company_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_company\\"/>\\n                                <field name=\\"reference\\" readonly=\\"1\\" invisible=\\"not reference\\"/>\\n                                <field name=\\"client_order_ref\\"/>\\n                                <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'on_tag_click': 'edit_color', 'no_create_edit': True}\\"/>\\n                            </group>\\n                            <group name=\\"sale_info\\" string=\\"Invoicing\\">\\n                                <label for=\\"fiscal_position_id\\"/>\\n                                <div class=\\"o_row\\">\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\"/>\\n                                </div>\\n                                <field name=\\"preferred_payment_method_line_id\\"/>\\n                                <field name=\\"partner_invoice_id\\" groups=\\"!account.group_delivery_invoice_address\\" invisible=\\"1\\"/>\\n                                <field name=\\"journal_id\\" groups=\\"base.group_no_one\\" readonly=\\"invoice_count != 0 and state == 'sale'\\"/>\\n                                <field name=\\"invoice_status\\" invisible=\\"state != 'sale'\\" groups=\\"base.group_no_one\\"/>\\n                                <!-- test_event_configurator -->\\n                                <field name=\\"invoice_status\\" invisible=\\"1\\" groups=\\"!base.group_no_one\\"/>\\n                            </group>\\n                            <group name=\\"sale_shipping\\" string=\\"Shipping\\">\\n                                <field name=\\"incoterm\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                                <field name=\\"incoterm_location\\"/>\\n                            </group>\\n                            <group name=\\"sale_reporting\\" string=\\"Tracking\\">\\n                                <field name=\\"origin\\"/>\\n                                <field name=\\"campaign_id\\" options=\\"{'create_name_field': 'title'}\\"/>\\n                                <field name=\\"medium_id\\" readonly=\\"1\\"/>\\n                                <field name=\\"source_id\\"/>\\n                                <field name=\\"utm_reference\\" string=\\"Reference\\" options=\\"{'hide_model': True}\\" invisible=\\"not utm_reference\\" readonly=\\"True\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                </notebook>\\n            </sheet>\\n            <chatter/>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Sales Order" class="o_sale_order" js_class="sale_order_form">\n            <header>\n                <button string="Capture Transaction" name="payment_action_capture" type="object" data-hotkey="shift+g" class="oe_highlight" invisible="not has_authorized_transaction_ids"/>\n                <button string="Void Transaction" name="payment_action_void" type="object" data-hotkey="shift+v" confirm="Are you sure you want to void the authorized transaction? This action can't be undone." invisible="not has_authorized_transaction_ids"/>\n                <button string="Create Invoice" id="create_invoice" name="497" type="action" class="btn-primary" data-hotkey="q" invisible="invoice_status != 'to invoice' and not (has_overages and invoice_status == 'upselling')"/>\n                <button string="Create Invoice" id="create_invoice_percentage" name="497" type="action" context="{'default_advance_payment_method': 'percentage'}" data-hotkey="q" invisible="invoice_status != 'no' or state != 'sale'"/>\n                <button string="Send" id="quotation_send_primary" name="action_quotation_send" type="object" context="{'validate_analytic': True, 'check_document_layout': True}" class="btn-primary" data-hotkey="g" invisible="state != 'draft'"/>\n                <button string="Send PRO FORMA Invoice" id="send_proforma_primary" name="action_quotation_send" type="object" context="{'proforma': True, 'validate_analytic': True}" class="btn-primary" groups="sale.group_proforma_sales" invisible="state != 'draft' or invoice_count &gt;= 1"/>\n                <button string="Confirm" id="action_confirm" name="action_confirm" type="object" context="{'validate_analytic': True}" class="btn-primary" data-hotkey="q" invisible="state != 'sent'"/>\n                <button string="Download" name="sale.action_report_saleorder" type="action" data-hotkey="i" invisible="state == 'sale'"/>\n                <button string="Confirm" name="action_confirm" type="object" context="{'validate_analytic': True}" data-hotkey="q" invisible="state != 'draft'"/>\n                <button string="Send PRO FORMA Invoice" id="send_proforma" name="action_quotation_send" type="object" context="{'proforma': True, 'validate_analytic': True}" invisible="state == 'draft' or invoice_count &gt;= 1" groups="sale.group_proforma_sales"/>\n                <button string="Send" id="quotation_send" name="action_quotation_send" type="object" context="{'validate_analytic': True, 'check_document_layout': True}" data-hotkey="g" invisible="state not in ('sent', 'sale')"/>\n\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\n                <button string="Unlock" name="action_unlock" type="object" invisible="not locked" groups="sales_team.group_sale_manager"/>\n                <button string="Preview" name="action_preview_sale_order" type="object" class="btn-secondary"/>\n                <button string="Cancel" name="action_cancel" type="object" confirm-title="Cancel Order" confirm="Cancelling this order will set its status to 'Cancelled' and will update related documents and processes. Are you sure?" confirm-label="Yes, cancel order" cancel-label="No, go back" data-hotkey="x" invisible="state not in ['draft', 'sent', 'sale'] or not id or locked"/>\n                <button string="Set to Quotation" name="action_draft" type="object" data-hotkey="w" invisible="state != 'cancel'"/>\n                <t groups="sale.group_auto_done_setting">\n                    <button string="Lock" name="action_lock" type="object" help="If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver." invisible="locked or state != 'sale'" groups="sales_team.group_sale_manager"/>\n                </t>\n                <button string="Reopen Invoicing" name="action_reopen_order" type="object" class="btn-primary" invisible="not invoicing_closed or state != 'sale'" groups="sales_team.group_sale_manager"/>\n                <field name="state" widget="statusbar" statusbar_visible="draft,sent,sale"/>\n            </header>\n            <div class="alert alert-warning" role="alert" invisible="not sale_warning_text">\n                <field name="sale_warning_text" class="fw-bold"/>\n            </div>\n            <div class="alert alert-warning" role="alert" invisible="partner_credit_warning == ''">\n                <field name="partner_credit_warning"/>\n            </div>\n            <div class="alert alert-warning p-3 text-center" role="alert" invisible="state not in ['draft', 'sent'] or not has_archived_products">\n                <span>Warning: This quote contains archived product(s)</span>\n            </div>\n            <div class="alert alert-warning w-100 d-flex align-items-center gap-1" invisible="state != 'draft' or not duplicated_order_ids" role="alert">\n                <span>Warning: this order might be a duplicate of</span>\n                <field name="duplicated_order_ids" widget="x2many_buttons" string="Duplicated Documents"/>\n            </div>\n            <sheet>\n                <div class="oe_button_box" name="button_box">\n                    <button name="action_view_invoice" type="object" class="oe_stat_button" icon="edit_square" invisible="invoice_count == 0">\n                        <field name="invoice_count" widget="statinfo" string="Invoices"/>\n                    </button>\n                    <button name="action_view_payment_transaction" type="object" class="oe_stat_button" icon="payments" groups="account.group_account_invoice,base.group_no_one">\n                        <field name="transaction_count" widget="statinfo" string="Payments"/>\n                    </button>\n                </div>\n                <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                    <i class="oi" data-icon="lock"/>\n                    Locked\n                </div>\n                <div class="oe_title">\n                    <h1 class="o_outlined">\n                        <field name="name" readonly="1"/>\n                    </h1>\n                </div>\n                <group name="sale_header">\n                    <group name="partner_details">\n                        <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}" placeholder="Type to find a customer..." readonly="state in ['cancel', 'sale']"/>\n                        <field name="partner_invoice_id" groups="account.group_delivery_invoice_address" options="{'no_quick_create': True}" context="{'default_type': 'invoice', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}" readonly="state == 'cancel' or locked"/>\n                        <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" options="{'no_quick_create': True}" context="{'default_type': 'delivery', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}" readonly="state == 'cancel' or locked"/>\n                    </group>\n                    <group name="order_details">\n                        <field name="validity_date" invisible="state == 'sale'" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" groups="base.group_no_one" invisible="state in ['sale', 'cancel']">\n                            <label for="date_order" string="Quotation Date"/>\n                        </div>\n                        <field name="date_order" nolabel="1" groups="base.group_no_one" invisible="state in ['sale', 'cancel']" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" invisible="state in ['draft', 'sent']">\n                            <label for="date_order" string="Order Date"/>\n                        </div>\n                        <field name="date_order" nolabel="1" invisible="state in ['draft', 'sent']" readonly="state in ['cancel', 'sale']"/>\n                        <label for="pricelist_id" groups="product.group_product_pricelist" invisible="not has_active_pricelist"/>\n                        <div groups="product.group_product_pricelist" class="o_row" invisible="not has_active_pricelist">\n                            <field name="pricelist_id" options="{'no_open': True, 'no_create': True}" readonly="state in ['cancel', 'sale']"/>\n                        </div>\n                        <field name="currency_id" invisible="1"/>\n                        <field name="pricelist_id" invisible="1" readonly="state in ['cancel', 'sale']" groups="!product.group_product_pricelist"/>\n                        <field name="payment_term_id" placeholder="Immediate" options="{'no_open': True, 'no_create': True}"/>\n                        <label for="commitment_date" invisible="state == 'draft'"/>\n                        <label for="commitment_date" string="Delivery Date" invisible="state != 'draft'"/>\n                        <div name="commitment_date_div" class="o_row align-items-center">\n                            <field name="commitment_date" options="{'placeholder_field': 'expected_date'}" readonly="state == 'cancel' or locked"/>\n                            <field name="delivery_status" widget="badge" decoration-success="delivery_status == 'full'" decoration-warning="delivery_status == 'partial'" decoration-info="delivery_status in ['pending', 'started']" invisible="state != 'sale'"/>\n                        </div>\n                        <field name="expected_date" invisible="1"/>  <!-- Needed for the placeholder widget -->\n                   </group>\n                   <div>\n                        <field name="document_tax_mode" id="document_tax_mode_mobile" class="tax_mode_badge d-md-none" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'"/>\n                    </div>\n                </group>\n                <notebook>\n                    <page string="Order Lines" name="order_lines">\n                    <div class="position-relative document_tax_mode">\n                        <field name="document_tax_mode" id="document_tax_mode" class="overlap_badge_tab tax_mode_badge d-none d-md-block" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'"/>\n                    </div>\n                        <field name="order_line" widget="sol_o2m" mode="list,kanban" class="o_sale_order_line_o2m" readonly="state == 'cancel' or locked" aggregated_fields="price_subtotal,price_total" options="{'hide_composition': True, 'hide_prices': True, 'subsections': True}">\n                            <form>\n                                <field name="technical_price_unit" invisible="1"/>\n                                <!--\n                                    We need the sequence field to be here for new lines to be added at the correct position.\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\n                                -->\n                                <field name="sequence" invisible="1"/>\n                                <!-- Display_type must be specified as non readonly (which would be the case with the default field added by ORM) -->\n                                <field name="display_type" invisible="1"/>\n                                <group>\n                                    <group invisible="display_type">\n                                        <label for="product_id"/>\n                                        <div class="d-flex align-items-baseline">\n                                            <span class="oi text-warning me-1" data-icon="warning" title="This product is archived" invisible="state not in ['draft', 'sent'] or not is_product_archived"/>\n                                            <field name="product_id" context="{                                                     'default_uom_id': product_uom_id,                                                     'partner_id': parent.partner_id,                                                 }" readonly="not product_updatable" required="mandatory_product and not display_type and not is_downpayment" force_save="1" widget="many2one_barcode"/>\n                                        </div>\n                                        <field name="name"/>\n                                        <label for="product_uom_qty"/>\n                                        <div class="o_row" name="ordered_qty">\n                                            <field name="product_uom_qty"/>\n                                            <field name="product_uom_id" force_save="1" groups="uom.group_uom" class="oe_no_button" widget="many2one_uom" readonly="product_uom_readonly" required="not display_type and not is_downpayment"/>\n                                            <widget name="simple_qty_at_date_widget"/>\n                                        </div>\n                                        <label for="qty_delivered" string="Delivered" invisible="parent.state != 'sale'"/>\n                                        <div name="delivered_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_delivered" readonly="qty_delivered_method != 'manual'"/>\n                                        </div>\n                                        <label for="qty_invoiced" string="Invoiced" invisible="parent.state != 'sale'"/>\n                                        <div name="invoiced_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_invoiced"/>\n                                        </div>\n                                        <field name="price_unit"/>\n                                        <field name="tax_ids" widget="many2many_tax_tags" options="{'no_create': True}" context="{'search_view_ref': 'account.account_tax_view_search'}" readonly="qty_invoiced &gt; 0"/>\n                                        <t groups="sale.group_discount_per_so_line">\n                                            <label for="discount"/>\n                                            <div name="discount">\n                                                <field name="discount" class="oe_inline"/> %\n                                            </div>\n                                        </t>\n                                    </group>\n                                    <group invisible="display_type">\n                                        <label for="customer_lead"/>\n                                        <div name="lead">\n                                            <field name="customer_lead" class="oe_inline" readonly="product_type != 'consu'"/> days\n                                        </div>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'sale_order'}"/>\n                                    </group>\n                                </group>\n                                <label for="name" string="Section Name (eg. Products, Services)" invisible="display_type != 'line_section'"/>\n                                <label for="name" string="Subsection Name" invisible="display_type != 'line_subsection'"/>\n                                <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                <field name="name" invisible="not display_type"/>\n                                <group>\n                                    <field name="collapse_composition" string="Hide Composition" invisible="display_type not in ['line_section', 'line_subsection']" readonly="1"/>\n                                    <field name="collapse_prices" string="Hide Prices" invisible="display_type not in ['line_section', 'line_subsection']" readonly="1"/>\n                                </group>\n                                <field name="invoice_lines" invisible="1"/>\n                            </form>\n                            <list name="sol_list" string="Sales Order Lines" editable="bottom" limit="200" decoration-warning="(state in ['draft', 'sent'] and is_product_archived) or sale_line_warn_msg">\n                                <control>\n                                    <create string="Add Line" name="add_product_control" data-hotkey="shift+p"/>\n                                    <create string="Add Section" name="add_section_control" data-hotkey="shift+h" context="{'default_display_type': 'line_section'}"/>\n                                    <create string="Add Note" name="add_note_control" data-hotkey="shift+n" context="{'default_display_type': 'line_note'}"/>\n                                    <button string="Catalog" data-hotkey="shift+k" name="action_add_from_catalog" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                </control>\n\n                                <!-- Non readonly invisible fields, must be specified manually, because fields added automatically by the ORM\n                                    are readonly, widgets fieldDependencies too -->\n                                <field name="display_type" column_invisible="True"/>\n                                <field name="product_custom_attribute_value_ids" column_invisible="1">\n                                    <list>\n                                        <field name="custom_product_template_attribute_value_id"/>\n                                        <field name="custom_value"/>\n                                    </list>\n                                </field>\n                                <field name="product_no_variant_attribute_value_ids" column_invisible="1"/>\n                                <field name="technical_price_unit" column_invisible="1"/>\n                                <field name="linked_line_id" column_invisible="1"/>\n                                <field name="combo_item_id" column_invisible="1"/>\n                                <field name="selected_combo_items" column_invisible="1"/>\n                                <field name="virtual_id" column_invisible="1"/>\n                                <field name="linked_virtual_id" column_invisible="1"/>\n                                <field name="collapse_composition" column_invisible="1"/>\n                                <field name="collapse_prices" column_invisible="1"/>\n\n                                <!-- Currency, needed for monetary widgets to display the currency symbol -->\n                                <field name="currency_id" column_invisible="True"/>\n\n                                <!-- Standard fields -->\n                                <field name="sequence" invisible="combo_item_id" widget="handle"/>\n                                <widget name="line_number" nolabel="1" column_invisible="not parent.show_sol_numbers" width="29px"/>\n                                <column name="product_and_description" string="Description">\n                                    <field name="product_template_id" string="Product" readonly="id and not product_updatable" required="mandatory_product and not display_type and not is_downpayment" context="{                                             'default_list_price': price_unit,                                             'default_uom_id': product_uom_id,                                             'partner_id': parent.partner_id,                                         }" optional="hide" widget="sol_product_many2one" placeholder="Type to find a product..." invisible="display_type"/>\n                                    <field name="product_id" string="Product Variant" readonly="not product_updatable" required="mandatory_product and not display_type and not is_downpayment" force_save="1" context="{                                             'default_lst_price': price_unit,                                             'default_uom_id': product_uom_id,                                             'partner_id': parent.partner_id,                                         }" optional="hide" widget="sol_product_many2one" placeholder="Type to find a product..." invisible="display_type"/>\n                                    <field name="name" placeholder="Enter a description..." decoration-it="not display_type" required="display_type" widget="text"/>\n                                    <field name="label" widget="sol_label_text" context="{'partner_id': parent.partner_id}" invisible="display_type" required="1"/>\n                                </column>\n                                <field name="analytic_distribution" widget="analytic_distribution" options="{                                         'product_field': 'product_id',                                         'business_domain': 'sale_order',                                         'amount_field': 'price_subtotal',                                     }" optional="hide" groups="analytic.group_analytic_accounting"/>\n                                <column name="sol_qty">\n                                    <field name="product_uom_qty" invisible="display_type" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" readonly="is_downpayment"/>\n                                    <field name="section_qty" invisible="display_type not in ('line_section', 'line_subsection')" class="fw-normal text-muted"/>\n                                </column>\n                                <widget name="simple_qty_at_date_widget" width="20px"/>\n                                <column name="sol_uom" width="60px" groups="uom.group_uom">\n                                    <field name="product_uom_id" invisible="display_type" force_save="1" readonly="product_uom_readonly" required="not display_type and not is_downpayment" widget="many2one_uom" optional="show" options="{'no_open': True, 'no_create': True}"/>\n                                    <field name="section_uom_id" invisible="display_type not in ('line_section', 'line_subsection')" options="{'no_open': True, 'no_create': True}" class="fw-normal text-muted"/>\n                                </column>\n                                <column column_invisible="parent.state != 'sale'">\n                                    <field name="qty_delivered" string="Delivered" invisible="display_type" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" decoration-danger="qty_overage and qty_delivered &gt; qty_invoiced" readonly="qty_delivered_method != 'manual' or is_downpayment" optional="show"/>\n                                    <field name="qty_delivered_percent" widget="labeled_percentage_field" invisible="display_type" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" readonly="qty_delivered_method != 'manual' or is_downpayment or product_uom_qty == 0" optional="hide"/>\n                                </column>\n                                <field name="qty_invoiced" string="Invoiced" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" column_invisible="parent.state != 'sale'" optional="show"/>\n                                <field name="customer_lead" optional="hide" width="80px" readonly="parent.state not in ['draft', 'sent', 'sale'] or is_downpayment or product_type != 'consu'"/>\n                                <!--\n                                    price_unit is wrapped in a column so inheriting modules (e.g.\n                                    sale_margin) can add fields to it via position="inside" instead\n                                    of replacing the price_unit field node. A replace would silently\n                                    discard changes made by lower-priority inherited views and\n                                    require duplicating this definition.\n                                -->\n                                <column name="price_unit">\n                                    <field name="price_unit" invisible="display_type" readonly="qty_invoiced &gt; 0"/>\n                                </column>\n                                <field name="tax_ids" widget="many2many_tax_tags" options="{'no_create': True}" context="{'active_test': True}" readonly="qty_invoiced &gt; 0 or is_downpayment" optional="show"/>\n                                <field name="discount" string="Disc.%" groups="sale.group_discount_per_so_line" width="50px" optional="show"/>\n                                <column column_invisible="parent.document_tax_mode == 'tax_included'">\n                                    <field name="price_subtotal" string="Amount" invisible="is_downpayment"/>\n                                    <field name="price_subtotal" string="Tax Excl." invisible="display_type or is_downpayment" widget="labeled_monetary_field" optional="hide"/>\n                                    <field name="price_total" string="Tax Incl." invisible="display_type or is_downpayment" widget="labeled_monetary_field" optional="hide"/>\n                                </column>\n                                <column column_invisible="parent.document_tax_mode == 'tax_excluded'">\n                                    <field name="price_total" string="Amount" invisible="is_downpayment"/>\n                                    <field name="price_subtotal" string="Tax Excl." invisible="display_type or is_downpayment" widget="labeled_monetary_field" optional="hide"/>\n                                    <field name="price_total" string="Tax Incl." invisible="display_type or is_downpayment" widget="labeled_monetary_field" optional="hide"/>\n                                </column>\n                                <widget name="section_state"/>\n                            </list>\n                            <kanban class="o_kanban_mobile">\n                                <field name="product_custom_attribute_value_ids" column_invisible="1"/>\n                                <field name="product_template_id" column_invisible="1"/>\n                                <field name="combo_item_id" column_invisible="1"/>\n                                <field name="linked_line_id" column_invisible="1"/>\n                                <field name="selected_combo_items" column_invisible="1"/>\n                                <field name="virtual_id" column_invisible="1"/>\n                                <field name="linked_virtual_id" column_invisible="1"/>\n                                <field name="collapse_composition" column_invisible="1"/>\n                                <field name="collapse_prices" column_invisible="1"/>\n                                <field name="product_no_variant_attribute_value_ids" column_invisible="1"/>\n           